function reportsTab(which) {
  ['templates','schedules'].forEach(t => {
    el('rpt-tab-'+t)?.classList.toggle('active', t === which);
    el('rpt-pane-'+t)?.classList.toggle('active', t === which);
  });
  if (which === 'schedules') renderScheduledReports();
}

// ── Scheduled Reports Table ──

let _schedEditKey = null;

function renderScheduledReports() {
  const container = el('scheduled-reports-container');
  if (!container) return;

  const schedules = automationsCfg.report_schedules || {};
  const dayLabel = d => d ? d.charAt(0).toUpperCase() + d.slice(1) : '';

  // Show only reports that have been configured (have recipients)
  const configured = EMAILABLE_REPORTS.filter(r => {
    const cfg = schedules[r.key];
    return cfg && cfg.recipients;
  });

  const activeCount = configured.filter(r => (schedules[r.key] || {}).enabled).length;
  const badge = el('sched-active-badge');
  if (badge) badge.textContent = activeCount + ' of ' + configured.length + ' active';

  if (!configured.length) {
    if (badge) badge.textContent = '';
    container.innerHTML =
      '<div style="text-align:center;padding:40px 20px">' +
        '<div style="font-size:2rem;margin-bottom:8px">\u{1F4E7}</div>' +
        '<p style="font-size:var(--fs-lg);color:var(--text);font-weight:600;margin-bottom:4px">No report schedules configured</p>' +
        '<p style="font-size:var(--fs-base);color:var(--muted)">Switch to <strong>Report Templates</strong> and click the <strong>Email</strong> button on any report to set up a schedule.</p>' +
      '</div>';
    return;
  }

  const editSvg = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>';
  const checkSvg = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

  const theadCols =
    '<th>Report</th>' +
    '<th>Status</th>' +
    '<th>Frequency</th>' +
    '<th>Day / Time</th>' +
    '<th>Recipients</th>' +
    '<th>Last Sent</th>' +
    '<th style="width:140px">Actions</th>';

  const rows = configured.map(r => {
    const cfg = schedules[r.key] || {};
    const isEditing = _schedEditKey === r.key;

    const enabledHtml = '<label class="toggle-switch"><input type="checkbox" ' +
      (cfg.enabled ? 'checked' : '') +
      ' onchange="toggleSchedEnabled(\'' + r.key + '\', this.checked)"/><span class="toggle-slider"></span></label>';

    const freqText = (cfg.frequency === 'daily' ? 'Daily' : 'Weekly');
    const dayTimeText = cfg.frequency === 'daily'
      ? (cfg.time || '09:00')
      : dayLabel(cfg.day || 'monday') + ' @ ' + (cfg.time || '09:00');

    const recipText = (cfg.recipients || '').length > 30
      ? escHtml(cfg.recipients.substring(0, 28)) + '&hellip;'
      : escHtml(cfg.recipients || '\u2014');

    const lastSentText = cfg.last_sent
      ? new Date(cfg.last_sent).toLocaleDateString('en-US', { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
      : '\u2014';

    let inlineEditHtml = '';
    if (isEditing) {
      const days = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];
      inlineEditHtml = '<tr><td colspan="7" style="padding:0 12px 10px">' +
        '<div class="summary-inline-edit">' +
          '<div class="inline-field">' +
            '<label>Frequency</label>' +
            '<div style="display:flex;gap:10px">' +
              '<label style="font-size:var(--fs-base);display:flex;align-items:center;gap:4px"><input type="radio" name="sched-freq-' + r.key + '" value="daily" ' + (cfg.frequency === 'daily' ? 'checked' : '') + '/> Daily</label>' +
              '<label style="font-size:var(--fs-base);display:flex;align-items:center;gap:4px"><input type="radio" name="sched-freq-' + r.key + '" value="weekly" ' + (cfg.frequency !== 'daily' ? 'checked' : '') + '/> Weekly</label>' +
            '</div>' +
          '</div>' +
          '<div class="inline-field">' +
            '<label>Day</label>' +
            '<select id="sched-day-' + r.key + '" class="form-input" style="font-size:var(--fs-base);max-width:160px">' +
              days.map(d => '<option value="' + d + '"' + (cfg.day === d ? ' selected' : '') + '>' + dayLabel(d) + '</option>').join('') +
            '</select>' +
          '</div>' +
          '<div class="inline-field">' +
            '<label>Time</label>' +
            '<input type="time" id="sched-time-' + r.key + '" class="form-input" value="' + (cfg.time || '09:00') + '" style="font-size:var(--fs-base);max-width:140px"/>' +
          '</div>' +
          '<div class="inline-field">' +
            '<label>Recipients</label>' +
            '<input type="text" id="sched-recip-' + r.key + '" class="form-input" placeholder="team@company.com" value="' + escHtml(cfg.recipients || '') + '" style="font-size:var(--fs-base);flex:1"/>' +
          '</div>' +
          '<div class="inline-field">' +
            '<label>Subject Prefix</label>' +
            '<input type="text" id="sched-prefix-' + r.key + '" class="form-input" placeholder="[iQcadence Report]" value="' + escHtml(cfg.subject_prefix || '[iQcadence Report]') + '" style="font-size:var(--fs-base);flex:1"/>' +
          '</div>' +
          '<div style="margin-top:12px;display:flex;gap:8px;justify-content:flex-end">' +
            '<button class="btn btn-xs btn-ghost" style="color:var(--red)" onclick="removeReportSchedule(\'' + r.key + '\')">Remove Schedule</button>' +
            '<button class="btn btn-xs btn-primary" onclick="saveSchedInline(\'' + r.key + '\')">Save</button>' +
            '<button class="btn btn-xs btn-ghost" onclick="closeSchedInlineEdit()" style="color:var(--blue)">Done</button>' +
          '</div>' +
        '</div>' +
      '</td></tr>';
    }

    return '<tr class="' + (isEditing ? 'editing' : '') + (!cfg.enabled ? ' sched-disabled' : '') + '">' +
      '<td><strong>' + escHtml(r.label) + '</strong></td>' +
      '<td>' + enabledHtml + '</td>' +
      '<td style="font-size:var(--fs-base)">' + freqText + '</td>' +
      '<td style="font-size:var(--fs-base);color:var(--muted)">' + dayTimeText + '</td>' +
      '<td style="font-size:var(--fs-base);color:var(--muted);max-width:160px;overflow:hidden;text-overflow:ellipsis" title="' + escHtml(cfg.recipients || '') + '">' + recipText + '</td>' +
      '<td style="font-size:var(--fs-base);color:var(--muted)">' + lastSentText + '</td>' +
      '<td style="white-space:nowrap">' +
        '<button class="btn btn-xs btn-ghost" onclick="schedSendNow(\'' + r.key + '\')" title="Send Now" style="font-size:var(--fs-xs);padding:2px 6px">Send</button>' +
        '<button class="btn btn-xs btn-ghost" onclick="schedTestSend(\'' + r.key + '\')" title="Test (sends to you)" style="font-size:var(--fs-xs);padding:2px 6px;color:var(--muted)">Test</button>' +
        '<button class="btn btn-xs btn-ghost" onclick="toggleSchedInlineEdit(\'' + r.key + '\')" title="' + (isEditing ? 'Close' : 'Edit') + '">' + (isEditing ? checkSvg : editSvg) + '</button>' +
      '</td></tr>' +
      inlineEditHtml;
  }).join('');

  container.innerHTML =
    '<table class="alert-summary-table">' +
      '<thead><tr>' + theadCols + '</tr></thead>' +
      '<tbody>' + rows + '</tbody>' +
    '</table>' +
    '<p style="font-size:var(--fs-sm);color:var(--muted);margin-top:12px;font-style:italic">To add a new schedule, switch to Report Templates and click the Email button on any report.</p>';
}

function toggleSchedInlineEdit(reportKey) {
  _schedEditKey = (_schedEditKey === reportKey) ? null : reportKey;
  renderScheduledReports();
}

function closeSchedInlineEdit() {
  _schedEditKey = null;
  renderScheduledReports();
}

function toggleSchedEnabled(reportKey, enabled) {
  if (!automationsCfg.report_schedules) automationsCfg.report_schedules = {};
  if (!automationsCfg.report_schedules[reportKey]) return;
  automationsCfg.report_schedules[reportKey].enabled = enabled;
  saveAutomationsCfg();
  renderScheduledReports();
}

function saveSchedInline(reportKey) {
  if (!automationsCfg.report_schedules) automationsCfg.report_schedules = {};
  const cfg = automationsCfg.report_schedules[reportKey];
  if (!cfg) return;

  const freqRadio = document.querySelector('input[name="sched-freq-' + reportKey + '"]:checked');
  cfg.frequency = freqRadio ? freqRadio.value : 'weekly';
  cfg.day = el('sched-day-' + reportKey)?.value || 'monday';
  cfg.time = el('sched-time-' + reportKey)?.value || '09:00';
  cfg.recipients = (el('sched-recip-' + reportKey)?.value || '').trim();
  cfg.subject_prefix = (el('sched-prefix-' + reportKey)?.value || '[iQcadence Report]').trim();

  saveAutomationsCfg();
  _schedEditKey = null;
  renderScheduledReports();
  toast('Report schedule saved', 'success');
}

function removeReportSchedule(reportKey) {
  if (!automationsCfg.report_schedules || !automationsCfg.report_schedules[reportKey]) return;
  automationsCfg.report_schedules[reportKey].enabled = false;
  automationsCfg.report_schedules[reportKey].recipients = '';
  saveAutomationsCfg();
  _schedEditKey = null;
  renderScheduledReports();
  toast('Report schedule removed', 'success');
}

async function schedSendNow(reportKey) {
  const cfg = (automationsCfg.report_schedules || {})[reportKey];
  if (!cfg || !cfg.recipients) { toast('No recipients configured', 'warn'); return; }
  const { html, subject } = buildReportEmailPayload(reportKey);
  if (!html) { toast('Could not generate report  - no data', 'error'); return; }
  const prefix = cfg.subject_prefix || '[iQcadence Report]';
  try {
    toast('Sending report...', 'default');
    const { data, error } = await sb.functions.invoke('send-webhook', {
      body: { mode: 'email', recipients: cfg.recipients, subject: prefix + ' ' + subject,
              html_body: html, event_type: 'report_' + reportKey, customer_id: null, customer_name: null }
    });
    if (error) throw error;
    if (data?.error) throw new Error(data.error);
    cfg.last_sent = new Date().toISOString();
    saveAutomationsCfg();
    renderScheduledReports();
    toast('Report sent to ' + cfg.recipients.split(',').length + ' recipient(s)', 'success');
  } catch(err) {
    toast('Failed to send: ' + (err.message || 'Unknown error'), 'error');
  }
}

async function schedTestSend(reportKey) {
  if (!currentUser || !currentUser.email) { toast('No email on current user', 'error'); return; }
  const cfg = (automationsCfg.report_schedules || {})[reportKey];
  const { html, subject } = buildReportEmailPayload(reportKey);
  if (!html) { toast('Could not generate report  - no data', 'error'); return; }
  const prefix = (cfg && cfg.subject_prefix) || '[iQcadence Report]';
  try {
    toast('Sending test to ' + currentUser.email + '...', 'default');
    const { data, error } = await sb.functions.invoke('send-webhook', {
      body: { mode: 'email', recipients: currentUser.email, subject: prefix + ' ' + subject + ' (TEST)',
              html_body: html, event_type: 'report_test_' + reportKey, customer_id: null, customer_name: null }
    });
    if (error) throw error;
    if (data?.error) throw new Error(data.error);
    toast('Test report sent to ' + currentUser.email, 'success');
  } catch(err) {
    toast('Failed to send test: ' + (err.message || 'Unknown error'), 'error');
  }
}


// ─── AUTOMATIONS (Zapier Webhook Integration) ──────────────

function saveAutomationsCfg() {
  localStorage.setItem('iqc_automations', JSON.stringify(automationsCfg));
  const cid = getEffectiveClientId();
  if (currentUser && cid) {
    sb.from('settings').upsert({
      client_id:   cid,
      user_id:     currentUser.id,
      automations: JSON.stringify(automationsCfg),
      updated_at:  new Date().toISOString()
    }, { onConflict: 'client_id' }).then(({ error }) => {
      if (error) console.warn('Automations config sync failed:', error.message);
    });
  }
}

function migrateAutomationsCfg() {
  // Migrate old channel_threshold → alert_settings
  if (automationsCfg.channel_threshold !== undefined && !automationsCfg.alert_settings) {
    automationsCfg.alert_settings = { health_below_threshold: { threshold: automationsCfg.channel_threshold } };
    delete automationsCfg.channel_threshold;
  }
  // Ensure alert_settings exists with defaults
  if (!automationsCfg.alert_settings) automationsCfg.alert_settings = {};
  ALERT_TYPES.forEach(at => {
    if (!automationsCfg.alert_settings[at.key]) automationsCfg.alert_settings[at.key] = {};
    at.configFields.forEach(f => {
      if (automationsCfg.alert_settings[at.key][f.name] === undefined)
        automationsCfg.alert_settings[at.key][f.name] = f.default;
    });
  });
  // Ensure each channel has an alerts array - if missing, subscribe to all
  if (automationsCfg.channels) {
    ['slack', 'teams', 'email'].forEach(chKey => {
      if (automationsCfg.channels[chKey] && !automationsCfg.channels[chKey].alerts) {
        automationsCfg.channels[chKey].alerts = ALERT_TYPES.map(a => a.key);
      }
    });
  }
  // Ensure selected_alerts exists - derive from channel subscriptions or default to all
  if (!automationsCfg.selected_alerts) {
    const union = new Set();
    if (automationsCfg.channels) {
      ['slack', 'teams', 'email'].forEach(chKey => {
        (automationsCfg.channels[chKey]?.alerts || []).forEach(a => union.add(a));
      });
    }
    automationsCfg.selected_alerts = union.size > 0 ? [...union] : ALERT_TYPES.map(a => a.key);
  }
  // Ensure schedule exists with defaults
  if (!automationsCfg.schedule) {
    automationsCfg.schedule = { mode: 'realtime', daily_time: '09:00', weekly_day: 'monday', weekly_time: '09:00' };
  }
  // Ensure manager_scope exists with defaults
  if (!automationsCfg.manager_scope) {
    automationsCfg.manager_scope = { mode: 'all', managers: [] };
  }
  // Ensure report_schedules exists
  if (!automationsCfg.report_schedules) {
    automationsCfg.report_schedules = {};
  }
  // Ensure custom_rules array exists
  if (!automationsCfg.custom_rules) {
    automationsCfg.custom_rules = [];
  }
  // Migrate inline URLs to saved_connections
  if (!automationsCfg.saved_connections) {
    automationsCfg.saved_connections = [];
    if (automationsCfg.channels) {
      ['slack', 'teams', 'email'].forEach(function(chKey) {
        var ch = automationsCfg.channels[chKey];
        if (!ch) return;
        var isEmail = chKey === 'email';
        var hasValue = isEmail ? !!ch.recipients : !!ch.url;
        if (hasValue) {
          var conn = {
            id: generateConnectionId(),
            type: chKey,
            name: chKey === 'slack' ? 'Slack Channel' : chKey === 'teams' ? 'Teams Channel' : 'Email Recipients'
          };
          if (isEmail) {
            conn.recipients = ch.recipients;
            if (ch.subject_prefix) conn.subject_prefix = ch.subject_prefix;
          } else {
            conn.url = ch.url;
          }
          automationsCfg.saved_connections.push(conn);
          ch.connection_id = conn.id;
        }
      });
    }
    // Convert custom rule channel booleans to connection IDs
    (automationsCfg.custom_rules || []).forEach(function(rule) {
      if (!rule.channels) return;
      ['slack', 'teams', 'email'].forEach(function(chKey) {
        if (rule.channels[chKey] === true && automationsCfg.channels && automationsCfg.channels[chKey] && automationsCfg.channels[chKey].connection_id) {
          rule.channels[chKey] = automationsCfg.channels[chKey].connection_id;
        }
      });
    });
  }
  // Migrate legacy global alerts → alert_rules[]
  if (!automationsCfg.alert_rules && automationsCfg.selected_alerts && automationsCfg.selected_alerts.length) {
    var legacyRule = {
      id: 'ar-migrated-' + Date.now(),
      name: 'Migrated Alerts',
      enabled: true,
      alert_types: [].concat(automationsCfg.selected_alerts),
      settings: JSON.parse(JSON.stringify(automationsCfg.alert_settings || {})),
      channels: {},
      schedule: JSON.parse(JSON.stringify(automationsCfg.schedule || { mode: 'realtime' })),
      manager_scope: JSON.parse(JSON.stringify(automationsCfg.manager_scope || { mode: 'all', managers: [] })),
      created_at: new Date().toISOString(),
      created_by: (typeof currentUser !== 'undefined' && currentUser && currentUser.email) ? currentUser.email : 'system'
    };
    ['slack', 'teams', 'email'].forEach(function(k) {
      var ch = (automationsCfg.channels || {})[k];
      legacyRule.channels[k] = (ch && ch.enabled && ch.connection_id) ? ch.connection_id : false;
    });
    automationsCfg.alert_rules = [legacyRule];
  }
  if (!automationsCfg.alert_rules) automationsCfg.alert_rules = [];
}

function _newAlertRuleDraft() {
  return {
    id: 'ar-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
    name: '',
    enabled: true,
    alert_types: [],
    settings: {},
    channels: { slack: false, teams: false, email: false },
    schedule: { mode: 'realtime' },
    manager_scope: { mode: 'all', managers: [] },
    created_at: new Date().toISOString(),
    created_by: (typeof currentUser !== 'undefined' && currentUser && currentUser.email) ? currentUser.email : ''
  };
}

// ── Help search ──
function helpSearch() {
  var q = (el('help-search').value || '').trim().toLowerCase();
  var panes = document.querySelectorAll('#view-help .dtab-pane');
  var tabs = el('help-tab-row');
  var cards = document.querySelectorAll('#view-help .help-card');
  if (!q) {
    tabs.style.display = '';
    panes.forEach(function(p){ p.style.display = ''; p.classList.remove('active'); });
    var activeBtn = document.querySelector('#view-help .dtab.active');
    if (!activeBtn) activeBtn = document.querySelector('#view-help .dtab');
    if (activeBtn) activeBtn.click();
    cards.forEach(function(s){ s.style.display = ''; });
    // Also show hero blocks
    document.querySelectorAll('#view-help .help-hero').forEach(function(h){ h.style.display = ''; });
    var countEl = document.getElementById('help-search-count');
    if (countEl) countEl.style.display = 'none';
    return;
  }
  tabs.style.display = 'none';
  panes.forEach(function(p){ p.style.display = 'block'; p.classList.add('active'); });
  // Hide hero blocks during search
  document.querySelectorAll('#view-help .help-hero').forEach(function(h){ h.style.display = 'none'; });
  // Split query into words for multi-word matching
  var words = q.split(/\s+/).filter(Boolean);
  var count = 0;
  cards.forEach(function(s){
    var text = s.textContent.toLowerCase();
    var kw = (s.getAttribute('data-keywords') || '').toLowerCase();
    var combined = text + ' ' + kw;
    var match = words.every(function(w){ return combined.indexOf(w) !== -1; });
    s.style.display = match ? '' : 'none';
    if (match) count++;
  });
  // Show result count
  var countEl = document.getElementById('help-search-count');
  if (!countEl) {
    countEl = document.createElement('div');
    countEl.id = 'help-search-count';
    countEl.style.cssText = 'font-size:var(--fs-sm);color:var(--muted);margin-bottom:10px';
    el('help-tab-row').parentNode.insertBefore(countEl, el('help-tab-row').nextSibling);
  }
  countEl.style.display = '';
  countEl.textContent = count + ' result' + (count !== 1 ? 's' : '') + ' for "' + q + '"';
}

// ── Help tab switching ──
function helpTab(t) {
  document.querySelectorAll('#view-help .dtab').forEach(b => b.classList.remove('active'));
  document.querySelectorAll('#view-help .dtab-pane').forEach(p => p.classList.remove('active'));
  const btn = document.querySelector('#view-help .dtab[data-htab="' + t + '"]')
           || [...document.querySelectorAll('#view-help .dtab')].find(b => b.textContent.trim().toLowerCase().includes(t));
  if (btn) btn.classList.add('active');
  const pane = document.getElementById('help-pane-' + t);
  if (pane) pane.classList.add('active');
}

// ── Tab switching ──
function autoTab(which) {
  ['active','rules'].forEach(t => {
    el('auto-tab-'+t)?.classList.toggle('active', t === which);
    el('auto-pane-'+t)?.classList.toggle('active', t === which);
  });
  if (which === 'active') renderActiveAlerts();
  if (which === 'rules') renderCustomRulesList();
}

function openCreateAlertModal(ruleId) {
  if (ruleId) {
    var existing = (automationsCfg.alert_rules || []).find(function(r) { return r.id === ruleId; });
    if (existing) {
      _alertWizardDraft = JSON.parse(JSON.stringify(existing));
      _editingAlertRule = ruleId;
    } else {
      _alertWizardDraft = _newAlertRuleDraft();
      _editingAlertRule = null;
    }
  } else {
    _alertWizardDraft = _newAlertRuleDraft();
    _editingAlertRule = null;
  }
  _wizardStep = 1;
  openModal('create-alert-modal');
  wizardGoToStep(1);
  renderWizardNav();
}

function closeCreateAlertModal() {
  closeModal('create-alert-modal');
  _alertWizardDraft = null;
  _editingAlertRule = null;
  _wizardStep = 1;
}

// ── Main render ──
function renderAutomations() {
  // Hide Advanced tab button for users without api_webhooks (Pro+)
  const advBtn = el('auto-tab-advanced');
  if (advBtn) advBtn.style.display = hasFeature('api_webhooks') ? '' : 'none';
  autoTab('active');
  renderWebhookConfig();
  renderApiSection();
}

