// ── Portfolio average summary row for segment tables ──
function _segAvgRow(rows) {
  if (!rows.length) return '';
  const n     = rows.length;
  const avgCt = Math.round(rows.reduce((s, r) => s + r.count, 0) / n);
  const avgSc = Math.round(rows.reduce((s, r) => s + r.avgScore, 0) / n);
  const avgDt = Math.round(rows.reduce((s, r) => s + r.avgDelta, 0) / n * 10) / 10;
  const avgMrr = Math.round(rows.reduce((s, r) => s + r.totalMRR, 0) / n);
  const avgRPct = Math.round(rows.reduce((s, r) => s + r.riskPct, 0) / n);
  const avgRisk = Math.round(rows.reduce((s, r) => s + r.atRisk, 0) / n);
  const daysN = rows.filter(r => r.avgDays != null);
  const avgD  = daysN.length ? Math.round(daysN.reduce((s, r) => s + r.avgDays, 0) / daysN.length) : null;
  const avgRen = Math.round(rows.reduce((s, r) => s + r.renewals90, 0) / n);
  const scClr = avgSc >= (thresholds.healthy || 80) ? 'var(--green)' : avgSc >= (thresholds.watch || 65) ? 'var(--amber)' : avgSc >= (thresholds.risk || 50) ? 'var(--orange,#ea580c)' : 'var(--red)';
  const scBg  = avgSc >= 65 ? 'var(--green-l)' : avgSc >= 50 ? 'var(--amber-l)' : 'var(--red-l)';
  const tCls  = avgDt > 0 ? 'up' : avgDt < 0 ? 'dn' : 'flat';
  const tIco  = avgDt > 0 ? '▲' : avgDt < 0 ? '▼' : ' -';
  const tTxt  = avgDt > 0 ? '+' + avgDt : '' + avgDt;
  return `<tr style="background:linear-gradient(90deg,rgba(59,130,246,.10),rgba(59,130,246,.04));font-weight:700;font-size:1.05em;border-bottom:2.5px solid var(--blue,#3b82f6);letter-spacing:.01em">
    <td style="color:var(--blue);font-weight:800;text-transform:uppercase;font-size:var(--fs-xs);letter-spacing:.08em">Avg Across Segments</td>
    <td style="font-size:var(--fs-lg)">${avgCt}</td>
    <td><span style="display:inline-block;padding:3px 12px;border-radius:6px;font-size:var(--fs-md);font-weight:800;color:${scClr};background:${scBg}">${avgSc}</span></td>
    <td><span class="csm-trend ${tCls}" style="font-size:var(--fs-sm);padding:2px 8px;font-weight:800">${tIco} ${tTxt}</span></td>
    <td style="font-size:var(--fs-lg)">$${fmtNum(avgMrr)}</td>
    <td><span style="font-weight:800;color:${avgRPct > 30 ? 'var(--red)' : avgRPct > 0 ? 'var(--amber)' : 'var(--green)'}">${avgRPct}%</span> <span style="font-size:var(--fs-sm);color:var(--muted)">(${avgRisk})</span></td>
    <td style="font-size:var(--fs-lg)">${avgD != null ? avgD + 'd' : ' -'}</td>
    <td style="font-size:var(--fs-lg)">${avgRen}</td>
    <td></td>
  </tr>`;
}

// ── Segment Chart State ──
let _segChartMetric = 'score';
let _segChartRange = '90d';
let _segChartSelected = []; // empty = all segments
let _segChartTipData = [];

const SEG_CHART_COLORS = ['#3b82f6','#ef4444','#10b981','#f59e0b','#8b5cf6','#ec4899','#06b6d4','#84cc16','#f97316','#6366f1'];

function _segRangeToDays(range) {
  if (range === 'ytd') {
    const now = new Date();
    return Math.ceil((now - new Date(now.getFullYear(), 0, 1)) / 86400000);
  }
  return { '7d': 7, '30d': 30, '90d': 90, '6m': 180, '1y': 365, '2y': 730 }[range] || 90;
}

function aggregateSegmentByDay(custs, metricKey, cutoff) {
  const cfg = METRIC_CFG[metricKey] || METRIC_CFG.score;
  const isSumMetric = cfg.agg === 'sum';
  const isCountMetric = cfg.agg === 'count';
  const cutoffStr = cutoff.toISOString().slice(0, 10);
  const _todayStr = new Date().toISOString().slice(0, 10);

  // Generate every date from cutoff to yesterday so chart is continuous
  function _allDaysInRange() {
    const dates = [];
    const d = new Date(cutoff);
    while (d.toISOString().slice(0, 10) < _todayStr) {
      dates.push(d.toISOString().slice(0, 10));
      d.setDate(d.getDate() + 1);
    }
    return dates;
  }

  if (isSumMetric || isCountMetric) {
    const custEntries = [];
    custs.forEach(c => {
      const valForDate = {};
      (c.history || []).forEach(h => {
        if (!h.date) return;
        const val = cfg.val(h, c);
        if (val == null || typeof val !== 'number' || isNaN(val)) return;
        const key = new Date(h.date).toISOString().slice(0, 10);
        valForDate[key] = val;
      });
      const sortedDates = Object.keys(valForDate).sort();
      if (sortedDates.length) {
        custEntries.push({ valForDate, sortedDates });
      }
    });
    const dates = _allDaysInRange();
    return dates.map(date => {
      let total = 0, count = 0;
      custEntries.forEach(ce => {
        let val = null;
        for (let i = ce.sortedDates.length - 1; i >= 0; i--) {
          if (ce.sortedDates[i] <= date) { val = ce.valForDate[ce.sortedDates[i]]; break; }
        }
        if (val !== null) { total += val; count++; }
      });
      return { date, avg: isCountMetric ? count : total, _count: count };
    }).filter(p => p._count > 0).sort((a, b) => a.date.localeCompare(b.date));
  }

  // Avg metrics: forward-fill
  const custData = [];
  custs.forEach(c => {
    const dateMap = {};
    (c.history || []).forEach(h => {
      if (!h.date) return;
      const val = cfg.val(h, c);
      if (val == null || typeof val !== 'number' || isNaN(val)) return;
      const key = new Date(h.date).toISOString().slice(0, 10);
      dateMap[key] = val;
    });
    const sortedDates = Object.keys(dateMap).sort();
    if (sortedDates.length) {
      custData.push({ dateMap, sortedDates });
    }
  });
  const dates = _allDaysInRange();
  return dates.map(date => {
    let total = 0, count = 0;
    custData.forEach(cd => {
      let val = null;
      for (let i = cd.sortedDates.length - 1; i >= 0; i--) {
        if (cd.sortedDates[i] <= date) { val = cd.dateMap[cd.sortedDates[i]]; break; }
      }
      if (val !== null) { total += val; count++; }
    });
    return { date, avg: count ? total / count : 0, _count: count };
  }).filter(p => p._count > 0);
}

function toggleSegView(view) {
  _segView = view;
  _segChartSelected = []; // reset selection on view switch
  const segBtn = document.getElementById('seg-view-segments');
  const tierBtn = document.getElementById('seg-view-tiers');
  const stageBtn = document.getElementById('seg-view-stage');
  if (segBtn) segBtn.classList.toggle('active', view === 'segments');
  if (tierBtn) tierBtn.classList.toggle('active', view === 'tiers');
  if (stageBtn) stageBtn.classList.toggle('active', view === 'stage');
  const active = window._segActive;
  const dc = window._segDeltaCache;
  // Render tables first so _tierData/_stageData are populated before insights
  if (view === 'segments') {
    const segs = window._segData;
    if (segs) { renderSegTable(segs); renderSegChart(segs, active, dc); }
  } else if (view === 'stage') {
    if (active) { renderStageTable(active, dc); renderSegChart(window._segData, active, dc); }
  } else {
    if (active) { renderTierTable(active, dc); renderSegChart(window._segData, active, dc); }
  }
  // Now build insights with the freshly-populated view data
  const insightData = view === 'tiers' ? window._tierData : view === 'stage' ? window._stageData : window._segData;
  if (insightData && active) _buildSegInsights(insightData, active, view);
}

function toggleHideUntagged() {
  _hideUntagged = !_hideUntagged;
  localStorage.setItem('iqc_hide_untagged', _hideUntagged);
  renderSegments();
}

function renderSegments() {
  const kpiRow = el('seg-kpi-row');
  const tableWrap = el('seg-table-wrap');
  if (!kpiRow) return;

  const active = customers.filter(c => c.lifecycle !== 'churned' && passesManagerFilter(c));

  // Cache getDelta7d once per customer
  const deltaCache = new Map();
  active.forEach(c => deltaCache.set(c.id, getDelta7d(c)));

  // Build enriched segment data
  const tagMap = {};
  active.forEach(c => {
    (c.tags || []).forEach(tag => {
      if (!tagMap[tag]) tagMap[tag] = { tag, custs: [], totalMRR: 0, healthy: 0, watch: 0, atRisk: 0, riskMRR: 0, overdueCount: 0, renewals90: 0 };
      const seg = tagMap[tag];
      seg.custs.push(c);
      seg.totalMRR += (c.mrr || 0);
      if (c.status === 'healthy' || c.status === 'expand') seg.healthy++;
      else if (c.status === 'watch') seg.watch++;
      else if (c.status === 'critical' || c.status === 'risk') { seg.atRisk++; seg.riskMRR += (c.mrr || 0); }
      if (c.days != null && c.days >= 14) seg.overdueCount++;
      if (c.renewal != null && c.renewal > 0 && c.renewal <= 3) seg.renewals90++;
    });
  });

  // Collect untagged customers into a virtual segment
  const untaggedCustomers = active.filter(c => !c.tags || c.tags.length === 0);
  if (untaggedCustomers.length > 0) {
    tagMap[SEG_UNTAGGED] = { tag: SEG_UNTAGGED, custs: [], totalMRR: 0, healthy: 0, watch: 0, atRisk: 0, riskMRR: 0, overdueCount: 0, renewals90: 0 };
    const seg = tagMap[SEG_UNTAGGED];
    untaggedCustomers.forEach(c => {
      seg.custs.push(c);
      seg.totalMRR += (c.mrr || 0);
      if (c.status === 'healthy' || c.status === 'expand') seg.healthy++;
      else if (c.status === 'watch') seg.watch++;
      else if (c.status === 'critical' || c.status === 'risk') { seg.atRisk++; seg.riskMRR += (c.mrr || 0); }
      if (c.days != null && c.days >= 14) seg.overdueCount++;
      if (c.renewal != null && c.renewal > 0 && c.renewal <= 3) seg.renewals90++;
    });
  }

  const segments = Object.values(tagMap).map(seg => {
    seg.count = seg.custs.length;
    seg.avgScore = Math.round(seg.custs.reduce((s, c) => s + c.score, 0) / seg.count);
    seg.avgDelta = Math.round(seg.custs.reduce((s, c) => s + (deltaCache.get(c.id) || 0), 0) / seg.count * 10) / 10;
    seg.riskPct = Math.round((seg.atRisk / seg.count) * 100);
    seg.avgDays = seg.custs.filter(c => c.days != null).length
      ? Math.round(seg.custs.filter(c => c.days != null).reduce((s, c) => s + c.days, 0) / seg.custs.filter(c => c.days != null).length)
      : null;
    return seg;
  });

  // Apply "Hide Untagged" filter
  const visibleSegments = _hideUntagged ? segments.filter(s => s.tag !== SEG_UNTAGGED) : segments;

  // Cache for drill-down usage
  window._segData = visibleSegments;
  window._segDeltaCache = deltaCache;
  window._segActive = active;

  if (!visibleSegments.length) {
    const tagIcon = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/></svg>';
    kpiRow.innerHTML = '';
    if (tableWrap) tableWrap.innerHTML = `<div class="empty-st"><div class="ei" style="font-size:1.5rem;color:var(--muted)">${tagIcon}</div><h3>No tags yet</h3><p>Add tags to customers via the edit form or bulk-tag to create segments.</p></div>`;
    return;
  }

  const subtitle = el('seg-subtitle');
  if (subtitle) subtitle.textContent = `${visibleSegments.length} segment${visibleSegments.length !== 1 ? 's' : ''} \u00b7 ${active.length} accounts`;

  const showBtn = document.getElementById('seg-untag-show');
  const hideBtn = document.getElementById('seg-untag-hide');
  if (showBtn && hideBtn) {
    showBtn.classList.toggle('active', !_hideUntagged);
    hideBtn.classList.toggle('active', _hideUntagged);
  }

  renderSegKPIs(visibleSegments, active);
  // Render tables FIRST so _tierData/_stageData are populated before insights
  if (_segView === 'tiers') {
    renderTierTable(active, deltaCache);
  } else if (_segView === 'stage') {
    renderStageTable(active, deltaCache);
  } else {
    renderSegTable(visibleSegments);
  }
  // Now build insights with the freshly-populated view data
  const insightData = _segView === 'tiers' ? window._tierData : _segView === 'stage' ? window._stageData : visibleSegments;
  _buildSegInsights(insightData, active, _segView);
  renderSegChart(visibleSegments, active, deltaCache);
}

/* ── Segment KPI Cards ─────────────────────────────────────── */
function renderSegKPIs(segments, active) {
  const wrap = el('seg-kpi-row');
  if (!wrap) return;

  const _si = (path) => `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">${path}</svg>`;
  const icons = {
    tag:     _si('<path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"/><line x1="7" y1="7" x2="7.01" y2="7"/>'),
    people:  _si('<path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>'),
    dollar:  _si('<line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>'),
    alert:   _si('<path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>'),
    trendUp: _si('<polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/>'),
  };

  // Unique account count
  const uniqueIds = new Set();
  segments.forEach(seg => seg.custs.forEach(c => uniqueIds.add(c.id)));
  const uniqueCount = uniqueIds.size;

  // Total unique MRR (by unique customer)
  const mrrMap = new Map();
  segments.forEach(seg => seg.custs.forEach(c => mrrMap.set(c.id, c.mrr || 0)));
  const totalMRR = [...mrrMap.values()].reduce((s, v) => s + v, 0);

  // Risk MRR (unique customers that are at risk)
  const riskIds = new Set();
  segments.forEach(seg => seg.custs.filter(c => c.status === 'critical' || c.status === 'risk').forEach(c => riskIds.add(c.id)));
  const riskMRR = [...riskIds].reduce((s, id) => s + (mrrMap.get(id) || 0), 0);

  // Highest-risk segment (by riskPct, min 3 accounts)
  const qualifiedSegs = segments.filter(s => s.count >= 2);
  const highestRisk = qualifiedSegs.length ? qualifiedSegs.reduce((a, b) => a.riskPct > b.riskPct ? a : b) : null;
  const hrColor = 'dash-kpi-red';

  // Fastest growing segment (by avgDelta)
  const fastestGrow = segments.length ? segments.reduce((a, b) => a.avgDelta > b.avgDelta ? a : b) : null;

  // Dynamic number colors (headers stay static)
  const _segHrValColor = highestRisk ? (highestRisk.riskPct >= 40 ? '#dc2626' : highestRisk.riskPct >= 20 ? '#d97706' : '#16a34a') : '';
  const _segGrowValColor = fastestGrow ? (fastestGrow.avgDelta > 0 ? '#16a34a' : fastestGrow.avgDelta < 0 ? '#dc2626' : '') : '';

  wrap.innerHTML = `
    <div class="dash-kpi-card dash-kpi-blue">
      <div class="dash-kpi-hd"><div class="dash-kpi-icon">${icons.tag}</div><span class="dash-kpi-label">Total Segments <span class="info-tip tip-below" data-tip="Number of customer tag groups (segments) in your book.">\u24d8</span></span></div>
      <div class="dash-kpi-body"><div class="dash-kpi-num">${segments.length}</div><div class="dash-kpi-sub">customer tag groups</div></div>
    </div>
    <div class="dash-kpi-card dash-kpi-purple">
      <div class="dash-kpi-hd"><div class="dash-kpi-icon">${icons.people}</div><span class="dash-kpi-label">Total Accounts <span class="info-tip tip-below" data-tip="Unique customers across all segments. A customer in multiple segments is counted once.">\u24d8</span></span></div>
      <div class="dash-kpi-body"><div class="dash-kpi-num">${uniqueCount}</div><div class="dash-kpi-sub">across ${segments.length} segment${segments.length !== 1 ? 's' : ''}</div></div>
    </div>
    <div class="dash-kpi-card dash-kpi-teal">
      <div class="dash-kpi-hd"><div class="dash-kpi-icon">${icons.dollar}</div><span class="dash-kpi-label">Segment MRR <span class="info-tip tip-below" data-tip="Total monthly recurring revenue across all segmented accounts.">\u24d8</span></span></div>
      <div class="dash-kpi-body"><div class="dash-kpi-num">$${fmtNum(totalMRR)}</div><div class="dash-kpi-sub">${riskMRR > 0 ? '$' + fmtNum(riskMRR) + ' at risk' : 'No MRR at risk'}</div></div>
    </div>
    <div class="dash-kpi-card ${hrColor}">
      <div class="dash-kpi-hd"><div class="dash-kpi-icon">${icons.alert}</div><span class="dash-kpi-label">Highest-Risk <span class="info-tip tip-below" data-tip="Segment with the highest percentage of Critical/Risk customers (min 2 accounts).">\u24d8</span></span></div>
      <div class="dash-kpi-body"><div class="dash-kpi-num" style="font-size:1.4rem${_segHrValColor ? ';color:' + _segHrValColor : ''}">${highestRisk ? escHtml(segDisplayLabel(highestRisk.tag)) : ' -'}</div><div class="dash-kpi-sub">${highestRisk ? highestRisk.riskPct + '% at risk' : 'No data'}</div></div>
    </div>
    <div class="dash-kpi-card dash-kpi-green">
      <div class="dash-kpi-hd"><div class="dash-kpi-icon">${icons.trendUp}</div><span class="dash-kpi-label">Fastest-Growing <span class="info-tip tip-below" data-tip="Segment with the highest average health score improvement.">\u24d8</span></span></div>
      <div class="dash-kpi-body"><div class="dash-kpi-num" style="font-size:1.4rem${_segGrowValColor ? ';color:' + _segGrowValColor : ''}">${fastestGrow ? escHtml(segDisplayLabel(fastestGrow.tag)) : ' -'}</div><div class="dash-kpi-sub">${fastestGrow ? (fastestGrow.avgDelta >= 0 ? '+' : '') + fastestGrow.avgDelta + ' avg trend' : 'No data'}</div></div>
    </div>
  `;
}

/* ── Tier Table View ───────────────────────────────────────── */
function _buildTierData(active, deltaCache) {
  const tierDefs = [
    { key: 'smb',        label: 'SMB',        pill: 'tier-pill-smb' },
    { key: 'mid',        label: 'Mid-Market', pill: 'tier-pill-mid' },
    { key: 'enterprise', label: 'Enterprise', pill: 'tier-pill-ent' }
  ];
  return tierDefs.map(td => {
    const custs = active.filter(c => (c.tier || 'mid') === td.key);
    const count = custs.length;
    const totalMRR = custs.reduce((s, c) => s + (c.mrr || 0), 0);
    const avgScore = count ? Math.round(custs.reduce((s, c) => s + c.score, 0) / count) : 0;
    const avgDelta = count ? Math.round(custs.reduce((s, c) => s + (deltaCache.get(c.id) || 0), 0) / count * 10) / 10 : 0;
    const healthy = custs.filter(c => c.status === 'healthy' || c.status === 'expand').length;
    const watch = custs.filter(c => c.status === 'watch').length;
    const atRisk = custs.filter(c => c.status === 'critical' || c.status === 'risk').length;
    const riskPct = count ? Math.round((atRisk / count) * 100) : 0;
    const overdueCount = custs.filter(c => c.days != null && c.days >= 14).length;
    const renewals90 = custs.filter(c => c.renewal != null && c.renewal > 0 && c.renewal <= 3).length;
    const withDays = custs.filter(c => c.days != null);
    const avgDays = withDays.length ? Math.round(withDays.reduce((s, c) => s + c.days, 0) / withDays.length) : null;
    return { key: td.key, label: td.label, pill: td.pill, custs, count, totalMRR, avgScore, avgDelta, healthy, watch, atRisk, riskPct, overdueCount, renewals90, avgDays };
  });
}

function renderTierTable(active, deltaCache) {
  const wrap = el('seg-table-wrap');
  if (!wrap) return;

  const tiers = _buildTierData(active, deltaCache);
  window._tierData = tiers;

  const sortIcon = key => {
    if (tierSortKey !== key) return '';
    return tierSortDir === 'asc' ? ' ▲' : ' ▼';
  };
  const activeClass = key => tierSortKey === key ? 'seg-sort-active' : '';

  const sorted = [...tiers].sort((a, b) => {
    let va, vb;
    switch (tierSortKey) {
      case 'label':    va = a.label.toLowerCase(); vb = b.label.toLowerCase(); return tierSortDir === 'asc' ? (va < vb ? -1 : 1) : (va > vb ? -1 : 1);
      case 'count':    va = a.count; vb = b.count; break;
      case 'avgScore': va = a.avgScore; vb = b.avgScore; break;
      case 'avgDelta': va = a.avgDelta; vb = b.avgDelta; break;
      case 'mrr':      va = a.totalMRR; vb = b.totalMRR; break;
      case 'riskPct':  va = a.riskPct; vb = b.riskPct; break;
      case 'avgDays':  va = a.avgDays || 0; vb = b.avgDays || 0; break;
      case 'renewals': va = a.renewals90; vb = b.renewals90; break;
      default:         va = a.totalMRR; vb = b.totalMRR;
    }
    return tierSortDir === 'asc' ? va - vb : vb - va;
  });

  const chevronDown = '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>';
  const scoreColor = v => v >= (thresholds.healthy || 80) ? 'var(--green)' : v >= (thresholds.watch || 65) ? 'var(--amber)' : v >= (thresholds.risk || 50) ? 'var(--orange,#ea580c)' : 'var(--red)';

  const colCount = 9;
  window._tierColCount = colCount;

  wrap.innerHTML = `<div class="seg-table-wrap-scroll">
    <table class="ct" style="min-width:900px">
      <thead><tr>
        <th class="seg-sort-btn ${activeClass('label')}" onclick="sortTierTable('label')">Tier${sortIcon('label')}</th>
        <th class="seg-sort-btn ${activeClass('count')}" onclick="sortTierTable('count')">Accounts${sortIcon('count')}</th>
        <th class="seg-sort-btn ${activeClass('avgScore')}" onclick="sortTierTable('avgScore')">Avg Score${sortIcon('avgScore')}</th>
        <th class="seg-sort-btn ${activeClass('avgDelta')}" onclick="sortTierTable('avgDelta')">Trend (7d)${sortIcon('avgDelta')}</th>
        <th class="seg-sort-btn ${activeClass('mrr')}" onclick="sortTierTable('mrr')">MRR${sortIcon('mrr')}</th>
        <th class="seg-sort-btn ${activeClass('riskPct')}" onclick="sortTierTable('riskPct')">At-Risk %${sortIcon('riskPct')}</th>
        <th class="seg-sort-btn ${activeClass('avgDays')}" onclick="sortTierTable('avgDays')">Avg Contact${sortIcon('avgDays')}</th>
        <th class="seg-sort-btn ${activeClass('renewals')}" onclick="sortTierTable('renewals')">Renewals \u226490d${sortIcon('renewals')}</th>
        <th style="width:90px"></th>
      </tr></thead>
      <tbody id="seg-table-tbody">${_segAvgRow(sorted)}${sorted.map(t => {
        const trendCls = t.avgDelta > 0 ? 'up' : t.avgDelta < 0 ? 'dn' : 'flat';
        const trendIcon = t.avgDelta > 0 ? '▲' : t.avgDelta < 0 ? '▼' : ' -';
        const trendTxt = t.avgDelta > 0 ? '+' + t.avgDelta : '' + t.avgDelta;
        const contactStr = t.avgDays != null ? t.avgDays + 'd' : ' -';
        return `<tr class="seg-table-row" data-tier="${t.key}" onclick="drillTier('${t.key}')" style="cursor:pointer">
          <td><span class="tier-pill ${t.pill}">${t.label}</span></td>
          <td>${t.count}</td>
          <td><span style="display:inline-block;padding:2px 10px;border-radius:6px;font-size:var(--fs-base);font-weight:700;color:${scoreColor(t.avgScore)};background:${t.avgScore >= 65 ? 'var(--green-l)' : t.avgScore >= 50 ? 'var(--amber-l)' : 'var(--red-l)'}">${t.avgScore}</span></td>
          <td><span class="csm-trend ${trendCls}" style="font-size:var(--fs-xs);padding:1px 6px">${trendIcon} ${trendTxt}</span></td>
          <td>$${fmtNum(t.totalMRR)}</td>
          <td><span style="font-weight:700;color:${t.riskPct > 30 ? 'var(--red)' : t.riskPct > 0 ? 'var(--amber)' : 'var(--green)'}">${t.riskPct}%</span> <span style="font-size:var(--fs-sm);color:var(--muted)">(${t.atRisk})</span></td>
          <td>${contactStr}</td>
          <td>${t.renewals90}</td>
          <td><button class="btn-sm csm-expand-btn" onclick="event.stopPropagation();drillTier('${t.key}')">${chevronDown} Expand</button></td>
        </tr>`;
      }).join('')}</tbody>
    </table>
  </div>`;
}

function sortTierTable(key) {
  if (tierSortKey === key) tierSortDir = tierSortDir === 'asc' ? 'desc' : 'asc';
  else { tierSortKey = key; tierSortDir = key === 'label' ? 'asc' : 'desc'; }
  const active = window._segActive;
  const dc = window._segDeltaCache;
  if (active) renderTierTable(active, dc);
}

function drillTier(tierKey) {
  const tbody = el('seg-table-tbody');
  if (!tbody) return;
  const colCount = window._tierColCount || 9;

  const parentRow = tbody.querySelector(`tr.seg-table-row[data-tier="${tierKey}"]`);
  if (!parentRow) return;

  // Toggle off if already expanded
  const existingExpand = parentRow.nextElementSibling;
  if (existingExpand && existingExpand.classList.contains('seg-table-expand-row')) {
    existingExpand.remove();
    parentRow.classList.remove('seg-row-expanded');
    const btn = parentRow.querySelector('.csm-expand-btn');
    if (btn) btn.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg> Expand`;
    return;
  }

  parentRow.classList.add('seg-row-expanded');
  const btn = parentRow.querySelector('.csm-expand-btn');
  if (btn) btn.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="18 15 12 9 6 15"/></svg> Collapse`;

  const expandRow = document.createElement('tr');
  expandRow.className = 'seg-table-expand-row';
  expandRow.innerHTML = `<td colspan="${colCount}" class="seg-table-expand-cell">${buildTierDrillHTML(tierKey)}</td>`;
  parentRow.after(expandRow);
}

function buildTierDrillHTML(tierKey) {
  const tiers = window._tierData || [];
  const deltaCache = window._segDeltaCache || new Map();
  const tier = tiers.find(t => t.key === tierKey);
  if (!tier) return '<p>No data for this tier.</p>';

  const accs = tier.custs;
  const avgScore = tier.avgScore;
  const totalMRR = tier.totalMRR;
  const hmColor = v => v >= 65 ? 'var(--green)' : v >= 50 ? 'var(--amber)' : 'var(--red)';
  const dColor = tier.avgDelta > 0 ? 'var(--green)' : tier.avgDelta < 0 ? 'var(--red)' : 'var(--muted)';
  const dIcon = tier.avgDelta > 0 ? '▲' : tier.avgDelta < 0 ? '▼' : ' -';

  let summaryHTML = `<div class="csm-drill-stats">
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${hmColor(avgScore)}">${avgScore}</div>
      <div class="csm-drill-stat__label">Avg Score</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${dColor}">${dIcon} ${Math.abs(tier.avgDelta)}</div>
      <div class="csm-drill-stat__label">7d Trend</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val">${tier.count}</div>
      <div class="csm-drill-stat__label">Accounts</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val">$${fmtNum(totalMRR)}</div>
      <div class="csm-drill-stat__label">Total MRR</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:var(--green)">${tier.healthy}</div>
      <div class="csm-drill-stat__label">Healthy</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${tier.atRisk ? 'var(--red)' : 'var(--muted)'}">${tier.atRisk}</div>
      <div class="csm-drill-stat__label">At Risk</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${tier.overdueCount ? 'var(--red)' : 'var(--muted)'}">${tier.overdueCount}</div>
      <div class="csm-drill-stat__label">Overdue</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val">${tier.renewals90}</div>
      <div class="csm-drill-stat__label">Renewals \u226490d</div>
    </div>
  </div>`;

  // Sort by urgency
  const urgency = c => {
    const statusW = c.status === 'critical' ? 5 : c.status === 'risk' ? 4 : c.status === 'watch' ? 3 : c.status === 'healthy' ? 2 : 1;
    const renewalW = c.renewal != null && c.renewal > 0 ? Math.max(0, 13 - c.renewal) : 0;
    const mrrW = (c.mrr || 0) / 10000;
    const contactW = (c.days != null && c.days >= 14) ? 2 : 0;
    return (statusW * 10) + renewalW + mrrW + contactW;
  };
  const sorted = [...accs].sort((a, b) => urgency(b) - urgency(a));

  const OVERDUE_DAYS = 14;
  const tableHTML = `<table class="ct" style="min-width:auto;margin:0">
    <thead><tr>
      <th>Customer</th><th>Score</th><th>Trend</th><th>Status</th><th>MRR</th><th>Last Contact</th><th>Renewal</th><th>Lifecycle</th>
    </tr></thead>
    <tbody>${sorted.map(c => {
      const renewStr = c.renewal_date ? new Date(c.renewal_date).toLocaleDateString() : (c.renewal ? c.renewal + 'mo' : ' -');
      const isOverdue = c.days != null && c.days >= OVERDUE_DAYS;
      const delta = deltaCache.get(c.id) || 0;
      const trendHTML = delta > 0
        ? `<span class="csm-trend up" style="font-size:var(--fs-xs);padding:1px 6px">▲ +${delta}</span>`
        : delta < 0
          ? `<span class="csm-trend dn" style="font-size:var(--fs-xs);padding:1px 6px">▼ ${delta}</span>`
          : `<span class="csm-trend flat" style="font-size:var(--fs-xs);padding:1px 6px"> - 0</span>`;
      const contactCell = isOverdue
        ? `<span style="font-weight:700;color:var(--red)">${c.days}d ago</span> <span class="csm-overdue">OVERDUE</span>`
        : (c.days != null ? c.days + 'd ago' : ' -');
      return `<tr style="cursor:pointer" onclick="openDetail('${escHtml(c.id)}')">
        <td><strong>${escHtml(c.name)}</strong></td>
        <td><span style="display:inline-block;padding:2px 10px;border-radius:6px;font-size:var(--fs-base);font-weight:700;color:${c.score >= 65 ? 'var(--green)' : c.score >= 50 ? 'var(--amber)' : 'var(--red)'};background:${c.score >= 65 ? 'var(--green-l)' : c.score >= 50 ? 'var(--amber-l)' : 'var(--red-l)'}">${c.score}</span></td>
        <td>${trendHTML}</td>
        <td>${badgeHTML(c.status)}</td>
        <td>$${fmtNum(c.mrr || 0)}</td>
        <td>${contactCell}</td>
        <td>${renewStr}</td>
        <td style="font-size:var(--fs-base);color:var(--muted)">${c.lifecycle || ' -'}</td>
      </tr>`;
    }).join('')}</tbody>
  </table>`;

  const viewBtn = `<div style="text-align:right;margin-top:12px"><button class="btn-sm" onclick="filterByTier('${tierKey}')" style="gap:4px">View in Customers <span style="font-size:var(--fs-base)">\u2192</span></button></div>`;

  return summaryHTML + tableHTML + viewBtn;
}

/* ── Stage (Lifecycle) Table ─────────────────────────────────── */
let stageSortKey = 'mrr';
let stageSortDir = 'desc';

function _buildStageData(active, deltaCache) {
  const stageDefs = [
    { key: 'onboarding', label: 'Onboarding', pill: 'stage-pill-onb' },
    { key: 'active',     label: 'Active',     pill: 'stage-pill-act' },
    { key: 'atrisk',     label: 'At Risk',    pill: 'stage-pill-risk' },
    { key: 'won',        label: 'Won / Upsold', pill: 'stage-pill-won' },
    { key: 'churned',    label: 'Churned',    pill: 'stage-pill-churn' }
  ];
  return stageDefs.map(sd => {
    const custs = active.filter(c => (c.lifecycle || 'active') === sd.key);
    const count = custs.length;
    const totalMRR = custs.reduce((s, c) => s + (c.mrr || 0), 0);
    const avgScore = count ? Math.round(custs.reduce((s, c) => s + c.score, 0) / count) : 0;
    const avgDelta = count ? Math.round(custs.reduce((s, c) => s + (deltaCache.get(c.id) || 0), 0) / count * 10) / 10 : 0;
    const healthy = custs.filter(c => c.status === 'healthy' || c.status === 'expand').length;
    const watch = custs.filter(c => c.status === 'watch').length;
    const atRisk = custs.filter(c => c.status === 'critical' || c.status === 'risk').length;
    const riskPct = count ? Math.round((atRisk / count) * 100) : 0;
    const overdueCount = custs.filter(c => c.days != null && c.days >= 14).length;
    const renewals90 = custs.filter(c => c.renewal != null && c.renewal > 0 && c.renewal <= 3).length;
    const withDays = custs.filter(c => c.days != null);
    const avgDays = withDays.length ? Math.round(withDays.reduce((s, c) => s + c.days, 0) / withDays.length) : null;
    return { key: sd.key, label: sd.label, pill: sd.pill, custs, count, totalMRR, avgScore, avgDelta, healthy, watch, atRisk, riskPct, overdueCount, renewals90, avgDays };
  }).filter(s => s.count > 0);
}

function renderStageTable(active, deltaCache) {
  const wrap = el('seg-table-wrap');
  if (!wrap) return;

  const stages = _buildStageData(active, deltaCache);
  window._stageData = stages;

  const sortIcon = key => {
    if (stageSortKey !== key) return '';
    return stageSortDir === 'asc' ? ' ▲' : ' ▼';
  };
  const activeClass = key => stageSortKey === key ? 'seg-sort-active' : '';

  const sorted = [...stages].sort((a, b) => {
    let va, vb;
    switch (stageSortKey) {
      case 'label':    va = a.label.toLowerCase(); vb = b.label.toLowerCase(); return stageSortDir === 'asc' ? (va < vb ? -1 : 1) : (va > vb ? -1 : 1);
      case 'count':    va = a.count; vb = b.count; break;
      case 'avgScore': va = a.avgScore; vb = b.avgScore; break;
      case 'avgDelta': va = a.avgDelta; vb = b.avgDelta; break;
      case 'mrr':      va = a.totalMRR; vb = b.totalMRR; break;
      case 'riskPct':  va = a.riskPct; vb = b.riskPct; break;
      case 'avgDays':  va = a.avgDays || 0; vb = b.avgDays || 0; break;
      case 'renewals': va = a.renewals90; vb = b.renewals90; break;
      default:         va = a.totalMRR; vb = b.totalMRR;
    }
    return stageSortDir === 'asc' ? va - vb : vb - va;
  });

  const chevronDown = '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>';
  const scoreColor = v => v >= (thresholds.healthy || 80) ? 'var(--green)' : v >= (thresholds.watch || 65) ? 'var(--amber)' : v >= (thresholds.risk || 50) ? 'var(--orange,#ea580c)' : 'var(--red)';

  const stageColors = { onboarding:'#3b82f6', active:'#10b981', atrisk:'#ef4444', won:'#8b5cf6', churned:'#64748b' };

  const colCount = 9;
  window._stageColCount = colCount;

  wrap.innerHTML = `<div class="seg-table-wrap-scroll">
    <table class="ct" style="min-width:900px">
      <thead><tr>
        <th class="seg-sort-btn ${activeClass('label')}" onclick="sortStageTable('label')">Stage${sortIcon('label')}</th>
        <th class="seg-sort-btn ${activeClass('count')}" onclick="sortStageTable('count')">Accounts${sortIcon('count')}</th>
        <th class="seg-sort-btn ${activeClass('avgScore')}" onclick="sortStageTable('avgScore')">Avg Score${sortIcon('avgScore')}</th>
        <th class="seg-sort-btn ${activeClass('avgDelta')}" onclick="sortStageTable('avgDelta')">Trend (7d)${sortIcon('avgDelta')}</th>
        <th class="seg-sort-btn ${activeClass('mrr')}" onclick="sortStageTable('mrr')">MRR${sortIcon('mrr')}</th>
        <th class="seg-sort-btn ${activeClass('riskPct')}" onclick="sortStageTable('riskPct')">At-Risk %${sortIcon('riskPct')}</th>
        <th class="seg-sort-btn ${activeClass('avgDays')}" onclick="sortStageTable('avgDays')">Avg Contact${sortIcon('avgDays')}</th>
        <th class="seg-sort-btn ${activeClass('renewals')}" onclick="sortStageTable('renewals')">Renewals \u226490d${sortIcon('renewals')}</th>
        <th style="width:90px"></th>
      </tr></thead>
      <tbody id="seg-table-tbody">${_segAvgRow(sorted)}${sorted.map(t => {
        const trendCls = t.avgDelta > 0 ? 'up' : t.avgDelta < 0 ? 'dn' : 'flat';
        const trendIcon = t.avgDelta > 0 ? '▲' : t.avgDelta < 0 ? '▼' : ' -';
        const trendTxt = t.avgDelta > 0 ? '+' + t.avgDelta : '' + t.avgDelta;
        const contactStr = t.avgDays != null ? t.avgDays + 'd' : ' -';
        const sc = stageColors[t.key] || '#64748b';
        return `<tr class="seg-table-row" data-stage="${t.key}" onclick="drillStage('${t.key}')" style="cursor:pointer">
          <td><span class="stage-pill" style="background:${sc}15;color:${sc};border:1px solid ${sc}30;padding:2px 10px;border-radius:6px;font-size:var(--fs-base);font-weight:700">${t.label}</span></td>
          <td>${t.count}</td>
          <td><span style="display:inline-block;padding:2px 10px;border-radius:6px;font-size:var(--fs-base);font-weight:700;color:${scoreColor(t.avgScore)};background:${t.avgScore >= 65 ? 'var(--green-l)' : t.avgScore >= 50 ? 'var(--amber-l)' : 'var(--red-l)'}">${t.avgScore}</span></td>
          <td><span class="csm-trend ${trendCls}" style="font-size:var(--fs-xs);padding:1px 6px">${trendIcon} ${trendTxt}</span></td>
          <td>$${fmtNum(t.totalMRR)}</td>
          <td><span style="font-weight:700;color:${t.riskPct > 30 ? 'var(--red)' : t.riskPct > 0 ? 'var(--amber)' : 'var(--green)'}">${t.riskPct}%</span> <span style="font-size:var(--fs-sm);color:var(--muted)">(${t.atRisk})</span></td>
          <td>${contactStr}</td>
          <td>${t.renewals90}</td>
          <td><button class="btn-sm csm-expand-btn" onclick="event.stopPropagation();drillStage('${t.key}')">${chevronDown} Expand</button></td>
        </tr>`;
      }).join('')}</tbody>
    </table>
  </div>`;
}

function sortStageTable(key) {
  if (stageSortKey === key) stageSortDir = stageSortDir === 'asc' ? 'desc' : 'asc';
  else { stageSortKey = key; stageSortDir = key === 'label' ? 'asc' : 'desc'; }
  const active = window._segActive;
  const dc = window._segDeltaCache;
  if (active) renderStageTable(active, dc);
}

function drillStage(stageKey) {
  const tbody = el('seg-table-tbody');
  if (!tbody) return;
  const colCount = window._stageColCount || 9;

  const parentRow = tbody.querySelector(`tr.seg-table-row[data-stage="${stageKey}"]`);
  if (!parentRow) return;

  // Toggle off if already expanded
  const existingExpand = parentRow.nextElementSibling;
  if (existingExpand && existingExpand.classList.contains('seg-table-expand-row')) {
    existingExpand.remove();
    parentRow.classList.remove('seg-row-expanded');
    const btn = parentRow.querySelector('.csm-expand-btn');
    if (btn) btn.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg> Expand`;
    return;
  }

  parentRow.classList.add('seg-row-expanded');
  const btn = parentRow.querySelector('.csm-expand-btn');
  if (btn) btn.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="18 15 12 9 6 15"/></svg> Collapse`;

  const expandRow = document.createElement('tr');
  expandRow.className = 'seg-table-expand-row';
  expandRow.innerHTML = `<td colspan="${colCount}" class="seg-table-expand-cell">${buildStageDrillHTML(stageKey)}</td>`;
  parentRow.after(expandRow);
}

function buildStageDrillHTML(stageKey) {
  const stages = window._stageData || [];
  const deltaCache = window._segDeltaCache || new Map();
  const stage = stages.find(t => t.key === stageKey);
  if (!stage) return '<p>No data for this stage.</p>';

  const accs = stage.custs;
  const avgScore = stage.avgScore;
  const totalMRR = stage.totalMRR;
  const hmColor = v => v >= 65 ? 'var(--green)' : v >= 50 ? 'var(--amber)' : 'var(--red)';
  const dColor = stage.avgDelta > 0 ? 'var(--green)' : stage.avgDelta < 0 ? 'var(--red)' : 'var(--muted)';
  const dIcon = stage.avgDelta > 0 ? '▲' : stage.avgDelta < 0 ? '▼' : ' -';

  let summaryHTML = `<div class="csm-drill-stats">
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${hmColor(avgScore)}">${avgScore}</div>
      <div class="csm-drill-stat__label">Avg Score</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${dColor}">${dIcon} ${Math.abs(stage.avgDelta)}</div>
      <div class="csm-drill-stat__label">7d Trend</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val">${stage.count}</div>
      <div class="csm-drill-stat__label">Accounts</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val">$${fmtNum(totalMRR)}</div>
      <div class="csm-drill-stat__label">Total MRR</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:var(--green)">${stage.healthy}</div>
      <div class="csm-drill-stat__label">Healthy</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${stage.atRisk ? 'var(--red)' : 'var(--muted)'}">${stage.atRisk}</div>
      <div class="csm-drill-stat__label">At Risk</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${stage.overdueCount ? 'var(--red)' : 'var(--muted)'}">${stage.overdueCount}</div>
      <div class="csm-drill-stat__label">Overdue</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val">${stage.renewals90}</div>
      <div class="csm-drill-stat__label">Renewals \u226490d</div>
    </div>
  </div>`;

  // Sort by urgency
  const urgency = c => {
    const statusW = c.status === 'critical' ? 5 : c.status === 'risk' ? 4 : c.status === 'watch' ? 3 : c.status === 'healthy' ? 2 : 1;
    const renewalW = c.renewal != null && c.renewal > 0 ? Math.max(0, 13 - c.renewal) : 0;
    const mrrW = (c.mrr || 0) / 10000;
    const contactW = (c.days != null && c.days >= 14) ? 2 : 0;
    return (statusW * 10) + renewalW + mrrW + contactW;
  };
  const sorted = [...accs].sort((a, b) => urgency(b) - urgency(a));

  const OVERDUE_DAYS = 14;
  const tableHTML = `<table class="ct" style="min-width:auto;margin:0">
    <thead><tr>
      <th>Customer</th><th>Score</th><th>Trend</th><th>Status</th><th>MRR</th><th>Last Contact</th><th>Renewal</th><th>Tier</th>
    </tr></thead>
    <tbody>${sorted.map(c => {
      const renewStr = c.renewal_date ? new Date(c.renewal_date).toLocaleDateString() : (c.renewal ? c.renewal + 'mo' : ' -');
      const isOverdue = c.days != null && c.days >= OVERDUE_DAYS;
      const delta = deltaCache.get(c.id) || 0;
      const trendHTML = delta > 0
        ? `<span class="csm-trend up" style="font-size:var(--fs-xs);padding:1px 6px">▲ +${delta}</span>`
        : delta < 0
          ? `<span class="csm-trend dn" style="font-size:var(--fs-xs);padding:1px 6px">▼ ${delta}</span>`
          : `<span class="csm-trend flat" style="font-size:var(--fs-xs);padding:1px 6px"> - 0</span>`;
      const contactCell = isOverdue
        ? `<span style="font-weight:700;color:var(--red)">${c.days}d ago</span> <span class="csm-overdue">OVERDUE</span>`
        : (c.days != null ? c.days + 'd ago' : ' -');
      const tierLabel = c.tier === 'enterprise' ? 'Enterprise' : c.tier === 'smb' ? 'SMB' : 'Mid-Market';
      return `<tr style="cursor:pointer" onclick="openDetail('${escHtml(c.id)}')">
        <td><strong>${escHtml(c.name)}</strong></td>
        <td><span style="display:inline-block;padding:2px 10px;border-radius:6px;font-size:var(--fs-base);font-weight:700;color:${c.score >= 65 ? 'var(--green)' : c.score >= 50 ? 'var(--amber)' : 'var(--red)'};background:${c.score >= 65 ? 'var(--green-l)' : c.score >= 50 ? 'var(--amber-l)' : 'var(--red-l)'}">${c.score}</span></td>
        <td>${trendHTML}</td>
        <td>${badgeHTML(c.status)}</td>
        <td>$${fmtNum(c.mrr || 0)}</td>
        <td>${contactCell}</td>
        <td>${renewStr}</td>
        <td style="font-size:var(--fs-base);color:var(--muted)">${tierLabel}</td>
      </tr>`;
    }).join('')}</tbody>
  </table>`;

  const viewBtn = `<div style="text-align:right;margin-top:12px"><button class="btn-sm" onclick="filterByStage('${stageKey}')" style="gap:4px">View in Customers <span style="font-size:var(--fs-base)">\u2192</span></button></div>`;

  return summaryHTML + tableHTML + viewBtn;
}

function filterByStage(stageKey) {
  columnFilters = {};
  insightFilter = null;
  mrrExposureFilter = null;
  filterMode = stageKey === 'churned' ? 'churned' : 'all';
  _filterTier = null;
  _filterStage = stageKey;
  nav('customers');
  renderCustomers();
}

function clearStageFilter() {
  _filterStage = null;
  renderCustomers();
}

/* ── Segment Cards (enriched) ──────────────────────────────── */
function renderSegCardGrid(segments) {
  const wrap = el('seg-cards-wrap');
  if (!wrap) return;

  const sorted = [...segments].sort((a, b) => b.totalMRR - a.totalMRR);

  const scoreColor = v => v >= (thresholds.healthy || 80) ? 'var(--green)' : v >= (thresholds.watch || 65) ? 'var(--amber)' : v >= (thresholds.risk || 50) ? 'var(--orange,#ea580c)' : 'var(--red)';
  const scoreBg = v => v >= (thresholds.healthy || 80) ? 'var(--green-l)' : v >= (thresholds.watch || 65) ? 'var(--amber-l)' : v >= (thresholds.risk || 50) ? 'rgba(234,88,12,.1)' : 'var(--red-l)';

  let html = `<div class="seg-cards-grid">${sorted.map(seg => {
    const trendCls = seg.avgDelta > 0 ? 'up' : seg.avgDelta < 0 ? 'dn' : 'flat';
    const trendIcon = seg.avgDelta > 0 ? '▲' : seg.avgDelta < 0 ? '▼' : ' -';
    const trendTxt = seg.avgDelta > 0 ? '+' + seg.avgDelta : '' + seg.avgDelta;
    const total = seg.healthy + seg.watch + seg.atRisk;
    const hPct = total ? Math.round((seg.healthy / total) * 100) : 0;
    const wPct = total ? Math.round((seg.watch / total) * 100) : 0;
    const rPct = total ? 100 - hPct - wPct : 0;
    const safeTag = seg.tag.replace(/'/g, "\\'").replace(/"/g, '&quot;');

    return `<div class="card seg-card" data-seg="${escHtml(seg.tag)}" onclick="drillSegFromCard('${safeTag}')" style="cursor:pointer">
      <div class="card-hd-bar"><span class="card-hd-bar__title">${escHtml(segDisplayLabel(seg.tag))}</span><span class="card-hd-bar__badge">${seg.avgScore}</span></div>
      <div class="card-body">
      <div style="display:flex;align-items:baseline;gap:10px;margin-bottom:4px">
        <span style="font-size:1.7rem;font-weight:500;line-height:1;font-family:'DM Mono',monospace">${seg.count}</span>
        <span class="seg-card-trend ${trendCls}">${trendIcon} ${trendTxt}</span>
      </div>
      <div style="font-size:var(--fs-sm);color:var(--muted);margin-bottom:10px">account${seg.count !== 1 ? 's' : ''}</div>
      <div class="seg-health-bar" style="height:6px;margin-bottom:12px" title="${seg.healthy} healthy · ${seg.watch} watch · ${seg.atRisk} at risk">
        ${hPct ? `<span class="seg-health-seg" style="width:${hPct}%;background:var(--green)"></span>` : ''}
        ${wPct ? `<span class="seg-health-seg" style="width:${wPct}%;background:var(--amber)"></span>` : ''}
        ${rPct ? `<span class="seg-health-seg" style="width:${rPct}%;background:var(--red)"></span>` : ''}
      </div>
      <div class="seg-card__divider"></div>
      <div class="seg-card__row">
        <span class="seg-card__row-label">MRR</span>
        <span class="seg-card__row-val">$${fmtNum(seg.totalMRR)}</span>
      </div>
      <div class="seg-card__row">
        <span class="seg-card__row-label">At Risk</span>
        <span class="seg-card__row-val" style="color:${seg.atRisk ? 'var(--red)' : 'var(--green)'}">${seg.atRisk ? seg.atRisk + ' (' + seg.riskPct + '%)' : 'None'}</span>
      </div>
      ${seg.overdueCount ? `<div class="seg-card__row"><span class="seg-card__row-label">Overdue</span><span class="seg-card__row-val" style="color:var(--red)">${seg.overdueCount}</span></div>` : ''}
      </div>
    </div>`;
  }).join('')}</div>`;

  html += `<div id="seg-card-expand" class="seg-expand-panel"></div>`;
  wrap.innerHTML = html;
}

/* ── Segment Comparison Table ──────────────────────────────── */
function renderSegTable(segments) {
  const wrap = el('seg-table-wrap');
  if (!wrap) return;

  const sortIcon = key => {
    if (segSortKey !== key) return '';
    return segSortDir === 'asc' ? ' ▲' : ' ▼';
  };
  const activeClass = key => segSortKey === key ? 'seg-sort-active' : '';

  const sorted = [...segments].sort((a, b) => {
    let va, vb;
    switch (segSortKey) {
      case 'tag':      va = a.tag.toLowerCase(); vb = b.tag.toLowerCase(); return segSortDir === 'asc' ? (va < vb ? -1 : 1) : (va > vb ? -1 : 1);
      case 'count':    va = a.count; vb = b.count; break;
      case 'avgScore': va = a.avgScore; vb = b.avgScore; break;
      case 'avgDelta': va = a.avgDelta; vb = b.avgDelta; break;
      case 'mrr':      va = a.totalMRR; vb = b.totalMRR; break;
      case 'riskPct':  va = a.riskPct; vb = b.riskPct; break;
      case 'avgDays':  va = a.avgDays || 0; vb = b.avgDays || 0; break;
      case 'renewals': va = a.renewals90; vb = b.renewals90; break;
      default:         va = a.totalMRR; vb = b.totalMRR;
    }
    return segSortDir === 'asc' ? va - vb : vb - va;
  });

  const chevronDown = '<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>';
  const scoreColor = v => v >= (thresholds.healthy || 80) ? 'var(--green)' : v >= (thresholds.watch || 65) ? 'var(--amber)' : v >= (thresholds.risk || 50) ? 'var(--orange,#ea580c)' : 'var(--red)';

  const colCount = 9;
  window._segColCount = colCount;

  wrap.innerHTML = `<div class="seg-table-wrap-scroll">
    <table class="ct" style="min-width:900px">
      <thead><tr>
        <th class="seg-sort-btn ${activeClass('tag')}" onclick="sortSegTable('tag')">Segment${sortIcon('tag')}</th>
        <th class="seg-sort-btn ${activeClass('count')}" onclick="sortSegTable('count')">Accounts${sortIcon('count')}</th>
        <th class="seg-sort-btn ${activeClass('avgScore')}" onclick="sortSegTable('avgScore')">Avg Score${sortIcon('avgScore')}</th>
        <th class="seg-sort-btn ${activeClass('avgDelta')}" onclick="sortSegTable('avgDelta')">Trend (7d)${sortIcon('avgDelta')}</th>
        <th class="seg-sort-btn ${activeClass('mrr')}" onclick="sortSegTable('mrr')">MRR${sortIcon('mrr')}</th>
        <th class="seg-sort-btn ${activeClass('riskPct')}" onclick="sortSegTable('riskPct')">At-Risk %${sortIcon('riskPct')}</th>
        <th class="seg-sort-btn ${activeClass('avgDays')}" onclick="sortSegTable('avgDays')">Avg Contact${sortIcon('avgDays')}</th>
        <th class="seg-sort-btn ${activeClass('renewals')}" onclick="sortSegTable('renewals')">Renewals \u226490d${sortIcon('renewals')}</th>
        <th style="width:90px"></th>
      </tr></thead>
      <tbody id="seg-table-tbody">${_segAvgRow(sorted)}${sorted.map(seg => {
        const trendCls = seg.avgDelta > 0 ? 'up' : seg.avgDelta < 0 ? 'dn' : 'flat';
        const trendIcon = seg.avgDelta > 0 ? '▲' : seg.avgDelta < 0 ? '▼' : ' -';
        const trendTxt = seg.avgDelta > 0 ? '+' + seg.avgDelta : '' + seg.avgDelta;
        const safeTag = seg.tag.replace(/'/g, "\\'").replace(/"/g, '&quot;');
        const contactStr = seg.avgDays != null ? seg.avgDays + 'd' : ' -';
        return `<tr class="seg-table-row" data-seg="${escHtml(seg.tag)}" onclick="drillSeg('${safeTag}')" style="cursor:pointer">
          <td><strong>${escHtml(segDisplayLabel(seg.tag))}</strong></td>
          <td>${seg.count}</td>
          <td><span style="display:inline-block;padding:2px 10px;border-radius:6px;font-size:var(--fs-base);font-weight:700;color:${scoreColor(seg.avgScore)};background:${seg.avgScore >= 65 ? 'var(--green-l)' : seg.avgScore >= 50 ? 'var(--amber-l)' : 'var(--red-l)'}">${seg.avgScore}</span></td>
          <td><span class="csm-trend ${trendCls}" style="font-size:var(--fs-xs);padding:1px 6px">${trendIcon} ${trendTxt}</span></td>
          <td>$${fmtNum(seg.totalMRR)}</td>
          <td><span style="font-weight:700;color:${seg.riskPct > 30 ? 'var(--red)' : seg.riskPct > 0 ? 'var(--amber)' : 'var(--green)'}">${seg.riskPct}%</span> <span style="font-size:var(--fs-sm);color:var(--muted)">(${seg.atRisk})</span></td>
          <td>${contactStr}</td>
          <td>${seg.renewals90}</td>
          <td><button class="btn-sm csm-expand-btn" onclick="event.stopPropagation();drillSeg('${safeTag}')">${chevronDown} Expand</button></td>
        </tr>`;
      }).join('')}</tbody>
    </table>
  </div>`;
}

function sortSegTable(key) {
  if (segSortKey === key) segSortDir = segSortDir === 'asc' ? 'desc' : 'asc';
  else { segSortKey = key; segSortDir = key === 'tag' ? 'asc' : 'desc'; }
  const segments = window._segData;
  if (segments) renderSegTable(segments);
}

/* ── Shared Drill-Down Builder ─────────────────────────────── */
function buildSegDrillHTML(tagName) {
  const segments = window._segData || [];
  const deltaCache = window._segDeltaCache || new Map();
  const seg = segments.find(s => s.tag === tagName);
  if (!seg) return '<p>No data for this segment.</p>';

  const accs = seg.custs;
  const avgScore = seg.avgScore;
  const totalMRR = seg.totalMRR;
  const hmColor = v => v >= 65 ? 'var(--green)' : v >= 50 ? 'var(--amber)' : 'var(--red)';
  const dColor = seg.avgDelta > 0 ? 'var(--green)' : seg.avgDelta < 0 ? 'var(--red)' : 'var(--muted)';
  const dIcon = seg.avgDelta > 0 ? '▲' : seg.avgDelta < 0 ? '▼' : ' -';

  let summaryHTML = `<div class="csm-drill-stats">
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${hmColor(avgScore)}">${avgScore}</div>
      <div class="csm-drill-stat__label">Avg Score</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${dColor}">${dIcon} ${Math.abs(seg.avgDelta)}</div>
      <div class="csm-drill-stat__label">7d Trend</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val">${seg.count}</div>
      <div class="csm-drill-stat__label">Accounts</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val">$${fmtNum(totalMRR)}</div>
      <div class="csm-drill-stat__label">Total MRR</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:var(--green)">${seg.healthy}</div>
      <div class="csm-drill-stat__label">Healthy</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${seg.atRisk ? 'var(--red)' : 'var(--muted)'}">${seg.atRisk}</div>
      <div class="csm-drill-stat__label">At Risk</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val" style="color:${seg.overdueCount ? 'var(--red)' : 'var(--muted)'}">${seg.overdueCount}</div>
      <div class="csm-drill-stat__label">Overdue</div>
    </div>
    <div class="csm-drill-stat">
      <div class="csm-drill-stat__val">${seg.renewals90}</div>
      <div class="csm-drill-stat__label">Renewals \u226490d</div>
    </div>
  </div>`;

  // Sort by urgency
  const urgency = c => {
    const statusW = c.status === 'critical' ? 5 : c.status === 'risk' ? 4 : c.status === 'watch' ? 3 : c.status === 'healthy' ? 2 : 1;
    const renewalW = c.renewal != null && c.renewal > 0 ? Math.max(0, 13 - c.renewal) : 0;
    const mrrW = (c.mrr || 0) / 10000;
    const contactW = (c.days != null && c.days >= 14) ? 2 : 0;
    return (statusW * 10) + renewalW + mrrW + contactW;
  };
  const sorted = [...accs].sort((a, b) => urgency(b) - urgency(a));

  const OVERDUE_DAYS = 14;
  const tableHTML = `<table class="ct" style="min-width:auto;margin:0">
    <thead><tr>
      <th>Customer</th><th>Score</th><th>Trend</th><th>Status</th><th>MRR</th><th>Last Contact</th><th>Renewal</th><th>Lifecycle</th>
    </tr></thead>
    <tbody>${sorted.map(c => {
      const renewStr = c.renewal_date ? new Date(c.renewal_date).toLocaleDateString() : (c.renewal ? c.renewal + 'mo' : ' -');
      const isOverdue = c.days != null && c.days >= OVERDUE_DAYS;
      const delta = deltaCache.get(c.id) || 0;
      const trendHTML = delta > 0
        ? `<span class="csm-trend up" style="font-size:var(--fs-xs);padding:1px 6px">▲ +${delta}</span>`
        : delta < 0
          ? `<span class="csm-trend dn" style="font-size:var(--fs-xs);padding:1px 6px">▼ ${delta}</span>`
          : `<span class="csm-trend flat" style="font-size:var(--fs-xs);padding:1px 6px"> - 0</span>`;
      const contactCell = isOverdue
        ? `<span style="font-weight:700;color:var(--red)">${c.days}d ago</span> <span class="csm-overdue">OVERDUE</span>`
        : (c.days != null ? c.days + 'd ago' : ' -');
      return `<tr style="cursor:pointer" onclick="openDetail('${escHtml(c.id)}')">
        <td><strong>${escHtml(c.name)}</strong></td>
        <td><span style="display:inline-block;padding:2px 10px;border-radius:6px;font-size:var(--fs-base);font-weight:700;color:${c.score >= 65 ? 'var(--green)' : c.score >= 50 ? 'var(--amber)' : 'var(--red)'};background:${c.score >= 65 ? 'var(--green-l)' : c.score >= 50 ? 'var(--amber-l)' : 'var(--red-l)'}">${c.score}</span></td>
        <td>${trendHTML}</td>
        <td>${badgeHTML(c.status)}</td>
        <td>$${fmtNum(c.mrr || 0)}</td>
        <td>${contactCell}</td>
        <td>${renewStr}</td>
        <td style="font-size:var(--fs-base);color:var(--muted)">${c.lifecycle || ' -'}</td>
      </tr>`;
    }).join('')}</tbody>
  </table>`;

  const safeTag = tagName.replace(/'/g, "\\'");
  const viewBtn = `<div style="text-align:right;margin-top:12px"><button class="btn-sm" onclick="filterByTag('${safeTag}')" style="gap:4px">View in Customers <span style="font-size:var(--fs-base)">\u2192</span></button></div>`;

  return summaryHTML + tableHTML + viewBtn;
}

/* ── Table Row Expand (drillSeg) ───────────────────────────── */
function drillSeg(tagName) {
  const tbody = el('seg-table-tbody');
  if (!tbody) return;
  const colCount = window._segColCount || 9;

  const parentRow = tbody.querySelector(`tr.seg-table-row[data-seg="${CSS.escape(tagName)}"]`);
  if (!parentRow) return;

  // Toggle off if already expanded
  const existingExpand = parentRow.nextElementSibling;
  if (existingExpand && existingExpand.classList.contains('seg-table-expand-row')) {
    existingExpand.remove();
    parentRow.classList.remove('seg-row-expanded');
    const btn = parentRow.querySelector('.csm-expand-btn');
    if (btn) btn.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg> Expand`;
    return;
  }

  parentRow.classList.add('seg-row-expanded');
  const btn = parentRow.querySelector('.csm-expand-btn');
  if (btn) btn.innerHTML = `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="18 15 12 9 6 15"/></svg> Collapse`;

  const expandRow = document.createElement('tr');
  expandRow.className = 'seg-table-expand-row';
  expandRow.innerHTML = `<td colspan="${colCount}" class="seg-table-expand-cell">${buildSegDrillHTML(tagName)}</td>`;
  parentRow.after(expandRow);
}

/* ── Card Grid Expand (drillSegFromCard) ───────────────────── */
function drillSegFromCard(tagName) {
  const panel = document.getElementById('seg-card-expand');
  if (!panel) return;

  // Clear previous card highlight
  const prevCard = document.querySelector('.seg-card.seg-expanded');
  if (prevCard) prevCard.classList.remove('seg-expanded');

  // Toggle off if clicking same card
  if (panel.classList.contains('open') && panel.dataset.seg === tagName) {
    panel.classList.remove('open');
    panel.dataset.seg = '';
    panel.innerHTML = '';
    return;
  }

  // Highlight clicked card
  const card = document.querySelector(`.seg-card[data-seg="${CSS.escape(tagName)}"]`);
  if (card) card.classList.add('seg-expanded');

  panel.dataset.seg = tagName;
  panel.innerHTML = buildSegDrillHTML(tagName);
  panel.classList.add('open');
  panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

/* ── Cross-Segment Portfolio Insights ──────────────────────── */
function _buildSegInsights(segments, active, view) {
  const wrap = el('seg-insights-wrap');
  if (!wrap) return;
  if (segments.length < 2) { wrap.innerHTML = ''; return; }

  // View-aware labels
  const viewLabel = view === 'tiers' ? 'tier' : view === 'stage' ? 'stage' : 'segment';
  const viewLabelPlural = view === 'tiers' ? 'tiers' : view === 'stage' ? 'stages' : 'segments';
  const viewTitle = view === 'tiers' ? 'Cross-Tier' : view === 'stage' ? 'Cross-Stage' : 'Cross-Segment';

  const _si = (path) => `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">${path}</svg>`;
  const icCorr    = _si('<circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>');
  const icDollar  = _si('<line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>');
  const icAlert   = _si('<path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>');
  const icGap     = _si('<path d="M18 20V10"/><path d="M12 20V4"/><path d="M6 20v-6"/>');
  const icTrend   = _si('<polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>');
  const icPhone   = _si('<path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6A19.79 19.79 0 0 1 2.12 4.18 2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72c.127.96.361 1.903.7 2.81a2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0 1 22 16.92z"/>');
  const icCal     = _si('<rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/>');
  const icOverlap = _si('<circle cx="9" cy="12" r="5.5"/><circle cx="15" cy="12" r="5.5"/>');
  const icUp      = _si('<polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/>');

  const insights = [];
  const totalMRR = segments.reduce((s, seg) => s + (seg.totalMRR || 0), 0);
  const totalCount = segments.reduce((s, seg) => s + seg.count, 0);
  const portfolioAvgScore = totalCount > 0 ? Math.round(segments.reduce((s, seg) => s + seg.avgScore * seg.count, 0) / totalCount) : 0;

  // ── 1. Contact-Score Correlation ──
  const withDays = segments.filter(s => s.avgDays != null && s.count >= 2);
  if (withDays.length >= 3) {
    const n = withDays.length;
    const xs = withDays.map(s => s.avgDays);
    const ys = withDays.map(s => s.avgScore);
    const mx = xs.reduce((a, b) => a + b, 0) / n;
    const my = ys.reduce((a, b) => a + b, 0) / n;
    let num = 0, dx2 = 0, dy2 = 0;
    for (let i = 0; i < n; i++) {
      const dx = xs[i] - mx, dy = ys[i] - my;
      num += dx * dy; dx2 += dx * dx; dy2 += dy * dy;
    }
    const denom = Math.sqrt(dx2 * dy2);
    const r = denom > 0 ? num / denom : 0;
    if (Math.abs(r) > 0.5) {
      const sorted = [...withDays].sort((a, b) => a.avgDays - b.avgDays);
      const lo = sorted[0], hi = sorted[sorted.length - 1];
      const gap = Math.abs(lo.avgScore - hi.avgScore);
      if (r < -0.5) {
        insights.push({ score: Math.abs(r) * 10, icon: icCorr, color: 'var(--green)', bg: 'var(--green-l)',
          label: 'Contact Correlation', tags: [],
          text: `${viewLabelPlural.charAt(0).toUpperCase() + viewLabelPlural.slice(1)} with more frequent contact tend to score higher - <strong>${Math.abs(Math.round(r * 100))}% correlation</strong> across ${n} ${viewLabelPlural}. Average gap: <strong>${gap} points</strong> between most and least contacted.` });
      } else {
        insights.push({ score: Math.abs(r) * 10, icon: icCorr, color: 'var(--amber)', bg: 'var(--amber-l)',
          label: 'Inverse Contact Pattern', tags: [],
          text: `${viewLabelPlural.charAt(0).toUpperCase() + viewLabelPlural.slice(1)} contacted less frequently actually score higher - <strong>${Math.round(r * 100)}% positive correlation</strong>. This may indicate over-servicing struggling ${viewLabelPlural} or that healthy ${viewLabelPlural} need less touch.` });
      }
    }
  }

  // ── 2. MRR Concentration ──
  if (totalMRR > 0 && segments.length >= 3) {
    segments.forEach(seg => {
      const pct = Math.round(seg.totalMRR / totalMRR * 100);
      if (pct >= 40) {
        insights.push({ score: pct * 0.2, icon: icDollar, color: 'var(--amber)', bg: 'var(--amber-l)',
          label: 'MRR Concentration', tags: [seg.tag],
          text: `<strong>${escHtml(segDisplayLabel(seg.tag))}</strong> holds <strong>${pct}%</strong> of portfolio MRR ($${fmtNum(seg.totalMRR)} of $${fmtNum(totalMRR)}) - a concentrated risk if this ${viewLabel}'s health declines.` });
      }
    });
  }

  // ── 3. Health Disparity ──
  const scored = segments.filter(s => s.count >= 2);
  if (scored.length >= 2) {
    const best = scored.reduce((a, b) => a.avgScore > b.avgScore ? a : b);
    const worst = scored.reduce((a, b) => a.avgScore < b.avgScore ? a : b);
    const gap = best.avgScore - worst.avgScore;
    if (gap >= 15) {
      const acColor = gap >= 25 ? 'var(--red)' : 'var(--amber)';
      const acBg = gap >= 25 ? 'var(--red-l)' : 'var(--amber-l)';
      insights.push({ score: gap * 0.4, icon: icGap, color: acColor, bg: acBg,
        label: 'Health Disparity', tags: [best.tag, worst.tag],
        text: `<strong>${gap}-point</strong> health gap between ${viewLabelPlural}: <strong>${escHtml(segDisplayLabel(best.tag))}</strong> averages ${best.avgScore} while <strong>${escHtml(segDisplayLabel(worst.tag))}</strong> averages ${worst.avgScore}.` });
    }
  }

  // ── 4. Risk Clustering ──
  const totalAtRisk = segments.reduce((s, seg) => s + seg.atRisk, 0);
  if (totalAtRisk >= 3) {
    segments.forEach(seg => {
      const pct = Math.round(seg.atRisk / totalAtRisk * 100);
      if (pct >= 50) {
        insights.push({ score: pct * 0.2 + seg.atRisk, icon: icAlert, color: 'var(--red)', bg: 'var(--red-l)',
          label: 'Risk Clustering', tags: [seg.tag],
          text: `<strong>${pct}%</strong> of at-risk accounts (${seg.atRisk} of ${totalAtRisk}) are concentrated in <strong>${escHtml(segDisplayLabel(seg.tag))}</strong> - targeted intervention here would address the majority of portfolio risk.` });
      }
    });
  }

  // ── 5. Revenue-Health Inversion ──
  if (totalMRR > 0 && segments.length >= 2) {
    const byMRR = [...segments].sort((a, b) => b.totalMRR - a.totalMRR);
    const topSeg = byMRR[0];
    if (topSeg && topSeg.avgScore < portfolioAvgScore - 5) {
      const diff = portfolioAvgScore - topSeg.avgScore;
      insights.push({ score: diff * 0.5 + (topSeg.totalMRR / totalMRR) * 10, icon: icDollar, color: 'var(--red)', bg: 'var(--red-l)',
        label: 'Revenue-Health Inversion', tags: [topSeg.tag],
        text: `Your highest-revenue ${viewLabel} <strong>${escHtml(segDisplayLabel(topSeg.tag))}</strong> ($${fmtNum(topSeg.totalMRR)} MRR) scores <strong>${diff} points below</strong> the portfolio average of ${portfolioAvgScore} - revenue and health are misaligned.` });
    }
  }

  // ── 6. Trend Divergence ──
  const improving = segments.filter(s => s.avgDelta >= 1.0);
  const declining = segments.filter(s => s.avgDelta <= -1.0);
  if (improving.length >= 1 && declining.length >= 1) {
    const portfolioAvgDelta = totalCount > 0 ? Math.round(segments.reduce((s, seg) => s + seg.avgDelta * seg.count, 0) / totalCount * 10) / 10 : 0;
    if (Math.abs(portfolioAvgDelta) < 2) {
      insights.push({ score: (improving.length + declining.length) * 2 + Math.abs(improving[0].avgDelta) + Math.abs(declining[0].avgDelta),
        icon: icTrend, color: 'var(--amber)', bg: 'var(--amber-l)',
        label: 'Trend Divergence', tags: [],
        text: `<strong>${improving.length}</strong> ${viewLabel}${improving.length !== 1 ? 's' : ''} improving while <strong>${declining.length}</strong> ${declining.length !== 1 ? 'are' : 'is'} declining - the ${Math.abs(portfolioAvgDelta) < 0.5 ? 'flat' : 'near-flat'} portfolio average of ${portfolioAvgDelta >= 0 ? '+' : ''}${portfolioAvgDelta} masks real movement underneath.` });
    }
  }

  // ── 7. Contact Gap Outlier ──
  if (withDays.length >= 3) {
    const sorted = [...withDays].sort((a, b) => a.avgDays - b.avgDays);
    const median = sorted[Math.floor(sorted.length / 2)].avgDays;
    if (median > 0) {
      withDays.forEach(seg => {
        if (seg.avgDays >= median * 2 && seg.avgDays >= 10) {
          const ratio = Math.round(seg.avgDays / median * 10) / 10;
          insights.push({ score: ratio * 3 + seg.count, icon: icPhone, color: 'var(--amber)', bg: 'var(--amber-l)',
            label: 'Contact Gap', tags: [seg.tag],
            text: `<strong>${escHtml(segDisplayLabel(seg.tag))}</strong> averages <strong>${seg.avgDays} days</strong> since contact vs the ${median}-day median - a <strong>${ratio}x gap</strong> that may be contributing to ${seg.avgScore < portfolioAvgScore ? 'its below-average health score of ' + seg.avgScore : 'risk if left unaddressed'}.` });
        }
      });
    }
  }

  // ── 8. Renewal Exposure ──
  const totalRenewals = segments.reduce((s, seg) => s + seg.renewals90, 0);
  if (totalRenewals >= 3) {
    segments.forEach(seg => {
      const pct = Math.round(seg.renewals90 / totalRenewals * 100);
      if (pct >= 50) {
        const rColor = seg.riskPct > 30 ? 'var(--red)' : 'var(--amber)';
        const rBg = seg.riskPct > 30 ? 'var(--red-l)' : 'var(--amber-l)';
        insights.push({ score: pct * 0.2 + seg.renewals90, icon: icCal, color: rColor, bg: rBg,
          label: 'Renewal Exposure', tags: [seg.tag],
          text: `<strong>${pct}%</strong> of upcoming renewals (${seg.renewals90} of ${totalRenewals}) are in <strong>${escHtml(segDisplayLabel(seg.tag))}</strong>${seg.riskPct > 30 ? ' which also has ' + seg.riskPct + '% at-risk accounts - a compounding concern' : ' - worth ensuring this ' + viewLabel + ' is well-covered'}.` });
      }
    });
  }

  // ── 9. Segment Overlap ──
  let bestOverlap = null;
  for (let i = 0; i < segments.length; i++) {
    const aIds = new Set(segments[i].custs.map(c => c.id));
    for (let j = i + 1; j < segments.length; j++) {
      const bIds = new Set(segments[j].custs.map(c => c.id));
      const shared = [...aIds].filter(id => bIds.has(id)).length;
      const smaller = Math.min(aIds.size, bIds.size);
      if (smaller >= 2) {
        const overlapPct = Math.round(shared / smaller * 100);
        if (overlapPct >= 50 && (!bestOverlap || overlapPct > bestOverlap.pct)) {
          bestOverlap = { pct: overlapPct, shared, smaller, a: segments[i], b: segments[j] };
        }
      }
    }
  }
  if (bestOverlap) {
    insights.push({ score: bestOverlap.pct * 0.08 + bestOverlap.shared, icon: icOverlap, color: 'var(--blue)', bg: 'var(--blue-l, #dbeafe)',
      label: 'Segment Overlap', tags: [bestOverlap.a.tag, bestOverlap.b.tag],
      text: `<strong>${escHtml(segDisplayLabel(bestOverlap.a.tag))}</strong> and <strong>${escHtml(segDisplayLabel(bestOverlap.b.tag))}</strong> share <strong>${bestOverlap.pct}%</strong> of accounts (${bestOverlap.shared} of ${bestOverlap.smaller}) - their health metrics will naturally track together.` });
  }

  // ── 10. Recovery Signal ──
  segments.forEach(seg => {
    if (seg.avgDelta >= 2.0 && seg.riskPct >= 30 && seg.count >= 3) {
      insights.push({ score: seg.avgDelta * 2 + seg.riskPct * 0.2, icon: icUp, color: 'var(--green)', bg: 'var(--green-l)',
        label: 'Recovery Signal', tags: [seg.tag],
        text: `<strong>${escHtml(segDisplayLabel(seg.tag))}</strong> is trending up (<strong>+${seg.avgDelta} pts/wk</strong>) but still has ${seg.riskPct}% at-risk accounts (${seg.atRisk}/${seg.count}) - recovery may be underway. Watch for accounts crossing back into healthy status.` });
    }
  });

  // ── 11. Synthesis - combine related insights on same segment ──
  // Look for compound patterns: MRR concentration + poor health in same segment
  var _synthTags = {};
  insights.forEach(function(ins) {
    (ins.tags || []).forEach(function(t) {
      if (!_synthTags[t]) _synthTags[t] = [];
      _synthTags[t].push(ins.label);
    });
  });
  Object.keys(_synthTags).forEach(function(tag) {
    var labels = _synthTags[tag];
    if (labels.length < 2) return;
    var seg = segments.find(function(s) { return s.tag === tag; });
    if (!seg) return;
    var segName = escHtml(segDisplayLabel(tag));

    // MRR Concentration + Risk Clustering in same segment
    if (labels.indexOf('MRR Concentration') >= 0 && labels.indexOf('Risk Clustering') >= 0) {
      insights.push({ score: 20, icon: icAlert, color: 'var(--red)', bg: 'var(--red-l)',
        label: 'Compounding Risk', tags: [tag],
        text: `<strong>${segName}</strong> concentrates both high MRR and high risk - ${seg.riskPct}% at-risk accounts holding $${fmtNum(seg.totalMRR)} MRR. This ${viewLabel} is your single biggest exposure point.` });
    }

    // MRR Concentration + Revenue-Health Inversion
    if (labels.indexOf('MRR Concentration') >= 0 && labels.indexOf('Revenue-Health Inversion') >= 0) {
      insights.push({ score: 18, icon: icDollar, color: 'var(--red)', bg: 'var(--red-l)',
        label: 'Revenue at Risk', tags: [tag],
        text: `<strong>${segName}</strong> holds your largest MRR concentration but scores below portfolio average - revenue and health are misaligned in the ${viewLabel} that matters most.` });
    }

    // Contact Gap + Health Disparity (worst health + no contact)
    if (labels.indexOf('Contact Gap') >= 0 && labels.indexOf('Health Disparity') >= 0) {
      insights.push({ score: 15, icon: icPhone, color: 'var(--amber)', bg: 'var(--amber-l)',
        label: 'Neglect Pattern', tags: [tag],
        text: `<strong>${segName}</strong> has both the widest contact gap and a notable health disparity - infrequent touch may be driving the health difference.` });
    }

    // Renewal Exposure + Risk Clustering
    if (labels.indexOf('Renewal Exposure') >= 0 && labels.indexOf('Risk Clustering') >= 0) {
      insights.push({ score: 17, icon: icCal, color: 'var(--red)', bg: 'var(--red-l)',
        label: 'Renewal Pipeline Risk', tags: [tag],
        text: `<strong>${segName}</strong> has concentrated renewal exposure combined with high at-risk clustering - upcoming renewals in this ${viewLabel} are especially vulnerable.` });
    }
  });

  // ── Sort, store all, paginate 3 at a time ──
  insights.sort((a, b) => b.score - a.score);
  window._segCrossInsights = insights;
  window._segInsightPage = 0;
  window._segInsightView = view;
  _renderSegInsightPage(wrap, viewTitle);
}

function _renderSegInsightPage(wrap, viewTitle) {
  if (!wrap) wrap = el('seg-insights-wrap');
  if (!wrap) return;
  const insights = window._segCrossInsights || [];
  const page = window._segInsightPage || 0;
  const view = window._segInsightView || 'segments';
  const perPage = 3;
  const start = page * perPage;
  const slice = insights.slice(start, start + perPage);
  const totalPages = Math.ceil(insights.length / perPage);

  if (!slice.length) { wrap.innerHTML = ''; return; }

  // If no viewTitle passed, reconstruct it
  if (!viewTitle) {
    viewTitle = view === 'tiers' ? 'Cross-Tier' : view === 'stage' ? 'Cross-Stage' : 'Cross-Segment';
  }

  const hasMore = page < totalPages - 1;
  const hasPrev = page > 0;
  const pageLabel = totalPages > 1 ? ` <span style="font-size:var(--fs-xs);color:var(--muted);font-weight:400;margin-left:6px">${page + 1} of ${totalPages}</span>` : '';

  const navBtns = totalPages > 1 ? `<div style="display:flex;gap:6px;align-items:center;margin-left:auto">` +
    (hasPrev ? `<button class="btn btn-ghost btn-sm" onclick="_segInsightPrev()" style="font-size:var(--fs-xs);padding:2px 8px">&larr; Prev</button>` : '') +
    (hasMore ? `<button class="btn btn-ghost btn-sm" onclick="_segInsightNext()" style="font-size:var(--fs-xs);padding:2px 8px;background:var(--blue);color:#fff;border-color:var(--blue)">More &rarr;</button>` : '') +
    `</div>` : '';

  const navRow = totalPages > 1 ? `<div style="display:flex;align-items:center;justify-content:flex-end;margin-bottom:8px">${pageLabel}${navBtns}</div>` : '';

  wrap.innerHTML = navRow +
    slice.map((ins, i) => {
      const idx = start + i;
      const accentCls = ins.color === 'var(--green)' ? ' ta-card-green' : ins.color === 'var(--red)' ? ' ta-card-red' : ins.color === 'var(--amber)' ? ' ta-card-amber' : '';
      const clickable = view !== 'stage' && ins.tags && ins.tags.length > 0;
      return `<div class="ta-card${accentCls}${clickable ? ' ta-card-clickable' : ''}" style="border-left-color:${ins.color}${clickable ? '' : ';cursor:default'}" ${clickable ? `onclick="_segInsightFocus(${idx})"` : ''}>
      <div class="ta-icon" style="background:${ins.bg};color:${ins.color}">${ins.icon}</div>
      <div>
        <div class="ta-label">${ins.label}</div>
        <div class="ta-detail">${ins.text}</div>
      </div>
    </div>`;
    }).join('');
}

function _segInsightNext() {
  const insights = window._segCrossInsights || [];
  const perPage = 3;
  const totalPages = Math.ceil(insights.length / perPage);
  window._segInsightPage = Math.min((window._segInsightPage || 0) + 1, totalPages - 1);
  _renderSegInsightPage();
}

function _segInsightPrev() {
  window._segInsightPage = Math.max((window._segInsightPage || 0) - 1, 0);
  _renderSegInsightPage();
}

function _segInsightFocus(idx) {
  const insights = window._segCrossInsights;
  if (!insights || !insights[idx]) return;
  const tags = insights[idx].tags || [];
  if (!tags.length) return;
  if (_segChartSelected.length === tags.length && tags.every(t => _segChartSelected.includes(t))) {
    _segChartSelected = [];
  } else {
    _segChartSelected = [...tags];
  }
  _renderSegChartOnly();
}

function filterByTag(tag) {
  nav('customers');
  if (tag === SEG_UNTAGGED) {
    columnFilters['tags'] = { type: 'untagged' };
  } else {
    columnFilters['tags'] = { type: 'text', q: tag };
  }
  renderCustomers();
}

function filterByTier(tier) {
  // Clear all other filters so only the tier filter is active
  columnFilters = {};
  insightFilter = null;
  mrrExposureFilter = null;
  filterMode = 'all';
  _filterTier = tier;
  nav('customers');
  renderCustomers();
}

function clearTierFilter() {
  _filterTier = null;
  renderCustomers();
}

// Bulksheet export - all editable/importable fields (excludes auto-derived: score, status, created)
function exportBulksheet() {
  const filtered = customers.filter(c => passesManagerFilter(c));
  const hdr = 'name,manager,scoring_profile,mrr,arr,tier,lifecycle,logins_30d,feature_adoption_pct,open_tickets,nps,csat,days_since_contact,renewal_date,months_to_renewal,growth_signal,tags,since,next_touch,sentiment,note';
  const rows = filtered.map(c => {
    const latestNote = (c.notes||[]).length ? c.notes[c.notes.length-1].text : '';
    const latestSent = (c.sentiment||[]).length ? c.sentiment[c.sentiment.length-1].val : '';
    return [
      c.name, c.manager||'', c.scoring_profile||'Global Weights',
      c.mrr||0, c.arr||(c.mrr*12)||0, c.tier||'mid', c.lifecycle||'active',
      c.logins != null ? c.logins : '', c.adoption != null ? c.adoption : '',
      c.tickets != null ? c.tickets : '', c.nps != null ? c.nps : '',
      c.csat != null ? c.csat : '', c.days != null ? c.days : '',
      c.renewal_date||'', c.renewal||0, c.growth||'none',
      (c.tags||[]).join('|'), c.since||'', c.next_touch||'',
      latestSent, latestNote
    ].map(v => `"${String(v).replace(/"/g,'""')}"`)
    .join(',');
  });
  dlText(hdr + '\n' + rows.join('\n'), 'cs-health-bulksheet.csv', 'text/csv');
  toast(`Exported ${filtered.length} customer${filtered.length !== 1 ? 's' : ''} (bulksheet)`);
}

/* ═══════════════ SEGMENT COMPARISON CHART ═══════════════ */

function segChartMetricChanged(key) {
  _segChartMetric = key || 'score';
  _renderSegChartOnly();
}

function setSegChartRange(range) {
  _segChartRange = range;
  document.querySelectorAll('#seg-chart-range-row .dtab').forEach(b =>
    b.classList.toggle('active', b.dataset.range === range));
  _renderSegChartOnly();
}

function toggleSegChartPill(tag) {
  const idx = _segChartSelected.indexOf(tag);
  if (idx >= 0) {
    _segChartSelected.splice(idx, 1);
  } else {
    _segChartSelected.push(tag);
  }
  _renderSegChartOnly();
}

function segChartSelectAll() {
  _segChartSelected = [];
  _renderSegChartOnly();
}

function _renderSegChartOnly() {
  const data = _segView === 'tiers' ? window._tierData : _segView === 'stage' ? window._stageData : window._segData;
  if (!data || !data.length) return;
  _buildSegChartPills(data);
  _buildSegChartSVG(data);
  _buildSegChartAnalysis(data);
}

function renderSegChart(segments, active, deltaCache) {
  const card = el('seg-chart-card');
  if (!card) return;

  // Populate metric dropdown
  const sel = el('seg-chart-metric');
  if (sel && !sel.dataset.init) {
    sel.dataset.init = '1';
    sel.innerHTML = Object.keys(METRIC_CFG).map(k =>
      `<option value="${k}"${k === _segChartMetric ? ' selected' : ''}>${METRIC_CFG[k].label}</option>`
    ).join('');
  }

  const data = _segView === 'tiers' ? window._tierData : _segView === 'stage' ? window._stageData : segments;
  if (!data || !data.length) {
    const wrap = el('seg-chart-wrap');
    if (wrap) wrap.innerHTML = '<p style="color:var(--subtle);text-align:center;padding:40px 0;font-size:var(--fs-md)">Not enough data to display a comparison chart.</p>';
    return;
  }

  _buildSegChartPills(data);
  _buildSegChartSVG(data);
  _buildSegChartAnalysis(data);
}

function _segLabel(item) {
  return item.label || segDisplayLabel(item.tag) || item.key || '?';
}

function _buildSegChartPills(data) {
  const wrap = el('seg-chart-pills');
  if (!wrap) return;
  const isAll = _segChartSelected.length === 0;
  let html = `<button class="seg-pill${isAll ? ' active' : ''}" onclick="segChartSelectAll()">All</button>`;
  data.forEach((seg, i) => {
    const label = _segLabel(seg);
    const tag = seg.tag || seg.key || label;
    const color = SEG_CHART_COLORS[i % SEG_CHART_COLORS.length];
    const active = _segChartSelected.includes(tag);
    html += `<button class="seg-pill${active ? ' active' : ''}" style="${active ? 'background:' + color + ';border-color:' + color : ''}" onclick="toggleSegChartPill('${escHtml(tag)}')">`
      + `<span class="seg-pill-color" style="background:${color}"></span>${escHtml(label)}</button>`;
  });
  wrap.innerHTML = html;
}

function _buildSegChartSVG(data) {
  const wrap = el('seg-chart-wrap');
  if (!wrap) return;

  const metric = _segChartMetric || 'score';
  const cfg = METRIC_CFG[metric] || METRIC_CFG.score;
  const rangeDays = _segRangeToDays(_segChartRange);
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - rangeDays);
  cutoff.setHours(0, 0, 0, 0);

  // Determine which segments to chart
  let chartSegs;
  if (_segChartSelected.length > 0) {
    chartSegs = data.filter(s => _segChartSelected.includes(s.tag || s.key || _segLabel(s)));
  } else {
    chartSegs = data;
  }

  // Build lines
  const lines = [];
  chartSegs.forEach((seg, i) => {
    const pts = aggregateSegmentByDay(seg.custs, metric, cutoff);
    if (pts.length >= 2) {
      lines.push({
        label: _segLabel(seg),
        color: SEG_CHART_COLORS[data.indexOf(seg) % SEG_CHART_COLORS.length],
        width: 2,
        points: pts,
        tag: seg.tag || seg.key
      });
    }
  });

  if (!lines.length) {
    wrap.innerHTML = '<p style="color:var(--subtle);text-align:center;padding:40px 0;font-size:var(--fs-md)">Not enough history data for the selected segments.</p>';
    return;
  }

  const W = 960, H = 210;
  const pad = { top: 12, right: 48, bottom: 28, left: 40 };
  const cW = W - pad.left - pad.right;
  const cH = H - pad.top - pad.bottom;

  // Collect all dates
  const allDates = new Set();
  lines.forEach(l => l.points.forEach(p => allDates.add(p.date)));
  const dates = [...allDates].sort();

  const xScale = (i) => pad.left + (dates.length === 1 ? cW / 2 : (i / (dates.length - 1)) * cW);

  // Y-axis scale (reuse global _trendNiceScale)
  const yL = _trendNiceScale(lines, cfg.fixed || null);
  const yScaleL = (v) => pad.top + cH - ((v - yL.min) / (yL.max - yL.min || 1)) * cH;

  // Status bands if health score
  let bandSVG = '';
  if (metric === 'score') {
    const thresholds = window._clientThresholds || DEFAULT_THRESHOLDS;
    const bandDefs = [
      { y0: 0, y1: thresholds.critical, color: '#dc2626' },
      { y0: thresholds.critical, y1: thresholds.risk, color: '#ea580c' },
      { y0: thresholds.risk, y1: thresholds.watch, color: '#d97706' },
      { y0: thresholds.watch, y1: thresholds.healthy, color: '#16a34a' },
      { y0: thresholds.healthy, y1: 100, color: '#3b82f6' },
    ];
    bandSVG = bandDefs.map(b => {
      const y = yScaleL(b.y1);
      const h = yScaleL(b.y0) - y;
      return `<rect x="${pad.left}" y="${y}" width="${cW}" height="${h}" fill="${b.color}" opacity="0.055"/>`;
    }).join('');
  }

  // Grid lines + Y-axis labels
  const _chartFont = "'DM Mono',monospace";
  let gridSVG = '';
  if (metric === 'score' && cfg.fixed) {
    // Health score 0-100: faint guide lines at 25, 50, 75 + edge labels
    [0, 25, 50, 75, 100].forEach(v => {
      if (v < yL.min || v > yL.max) return;
      const y = yScaleL(v);
      const isEdge = v === yL.min || v === yL.max;
      if (!isEdge) {
        gridSVG += `<line x1="${pad.left}" y1="${y}" x2="${W - pad.right}" y2="${y}" stroke="#cbd5e1" stroke-width="0.5" opacity="0.45"/>`;
      }
      gridSVG += `<text x="${pad.left - 8}" y="${y + 3}" text-anchor="end" font-size="8" font-weight="500" font-family="${_chartFont}" fill="#94a3b8">${cfg.axFmt(v)}</text>`;
    });
  } else {
    // All other metrics: 4 evenly spaced guide lines
    const gRange = yL.max - yL.min;
    const gStep = gRange / 4;
    const _axDec = gStep < 1 ? 1 : 0;
    for (let i = 0; i <= 4; i++) {
      const v = yL.min + i * gStep;
      const y = yScaleL(v);
      const isEdge = i === 0 || i === 4;
      if (!isEdge) {
        gridSVG += `<line x1="${pad.left}" y1="${y}" x2="${W - pad.right}" y2="${y}" stroke="#cbd5e1" stroke-width="0.5" opacity="0.45"/>`;
      }
      const vLabel = _axDec ? v.toFixed(_axDec) : String(Math.round(v));
      gridSVG += `<text x="${pad.left - 8}" y="${y + 3}" text-anchor="end" font-size="8" font-weight="500" font-family="${_chartFont}" fill="#94a3b8">${cfg.axFmt(parseFloat(vLabel))}</text>`;
    }
  }

  // X-axis date labels
  const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  let xLabels = '';
  const _xLabelEvery = rangeDays <= 7 ? 1 : rangeDays <= 30 ? Math.ceil(dates.length / 12) : rangeDays <= 90 ? Math.ceil(dates.length / 10) : rangeDays <= 180 ? Math.ceil(dates.length / 8) : Math.ceil(dates.length / 7);
  const _showYear = rangeDays > 180;
  dates.forEach((d, i) => {
    const x = xScale(i);
    const parts = d.split('-');
    const yr = parts[0].slice(2);
    const mo = parseInt(parts[1]) - 1;
    const day = parseInt(parts[2]);
    if (i % Math.max(1, Math.ceil(_xLabelEvery / 2)) === 0) {
      xLabels += `<line x1="${x}" y1="${yScaleL(yL.min)}" x2="${x}" y2="${yScaleL(yL.min) + 3}" stroke="#e2e8f0" stroke-width="0.5" opacity="0.4"/>`;
    }
    if (i % _xLabelEvery === 0 || i === dates.length - 1) {
      let lbl;
      if (_showYear && day <= 7) {
        lbl = monthNames[mo] + " '" + yr;
      } else if (rangeDays > 90) {
        lbl = monthNames[mo] + ' ' + day;
      } else {
        lbl = monthNames[mo] + ' ' + day;
      }
      xLabels += `<text x="${x}" y="${H - pad.bottom + 16}" text-anchor="middle" font-size="8" font-family="${_chartFont}" fill="#94a3b8">${lbl}</text>`;
    }
  });

  // Draw lines
  let linesSVG = '';
  const dateIdx = {};
  dates.forEach((d, i) => { dateIdx[d] = i; });

  lines.forEach((line, lineIdx) => {
    const pts = line.points.filter(p => dateIdx[p.date] !== undefined && !isNaN(p.avg))
      .sort((a, b) => a.date.localeCompare(b.date));
    if (pts.length < 2) return;

    // Build xy points for smooth path - downsample for long ranges
    const xyPtsRaw = pts.map(p => ({ x: xScale(dateIdx[p.date]), y: yScaleL(p.avg) }));
    const _maxRPts = rangeDays > 365 ? 90 : rangeDays > 180 ? 120 : 9999;
    const xyPts = _downsampleXY(xyPtsRaw, _maxRPts);

    // Area fill (only for first line or single line)
    if (lines.length === 1 || lineIdx === 0) {
      const areaBottom = yScaleL(yL.min);
      const firstX = xyPts[0].x;
      const lastX = xyPts[xyPts.length - 1].x;
      const smoothTop = _smoothPath(xyPts);
      const cIdx = smoothTop.indexOf('C');
      const topCurve = cIdx >= 0 ? smoothTop.slice(cIdx) : `L${lastX},${xyPts[xyPts.length-1].y}`;
      const areaPath = `M${firstX},${areaBottom} L${firstX},${xyPts[0].y} ${topCurve} L${lastX},${areaBottom} Z`;
      linesSVG += `<defs><linearGradient id="segAreaGrad${lineIdx}" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${line.color}" stop-opacity="0.12"/>
        <stop offset="100%" stop-color="${line.color}" stop-opacity="0.01"/>
      </linearGradient></defs>`;
      linesSVG += `<path d="${areaPath}" fill="url(#segAreaGrad${lineIdx})"/>`;
    }

    // Smooth line
    const smoothD = _smoothPath(xyPts);
    linesSVG += `<path d="${smoothD}" fill="none" stroke="${line.color}" stroke-width="${line.width}" stroke-linecap="round" opacity="0.9"/>`;

    // No inline labels - hover tooltip shows exact values for all lines
  });

  // Build tooltip data (Map-based with carry-forward for reliable lookups)
  const _segLineMaps = lines.map(l => {
    const m = new Map();
    l.points.forEach(p => m.set(p.date, p.avg));
    return m;
  });
  const _segLineCarry = _segLineMaps.map(lm => {
    let last = null;
    return dates.map(d => {
      if (lm.has(d)) last = lm.get(d);
      return last;
    });
  });
  _segChartTipData = dates.map((d, di) => {
    const parts = d.split('-');
    const mo = parseInt(parts[1]) - 1;
    const day = parseInt(parts[2]);
    const dateLabel = monthNames[mo] + ' ' + day;
    const vals = lines.map((l, li) => {
      const val = _segLineCarry[li][di];
      return val !== null ? { label: l.label, color: l.color, val: cfg.fmt(val) } : null;
    }).filter(Boolean);
    return { dateLabel, vals };
  });

  // Hover columns
  let hoverSVG = '';
  const colW = dates.length > 1 ? cW / (dates.length - 1) : cW;
  dates.forEach((d, i) => {
    const cx = xScale(i);
    hoverSVG += `<rect x="${cx - colW / 2}" y="${pad.top}" width="${colW}" height="${cH}" fill="transparent" style="cursor:crosshair"
      onmouseenter="showSegChartTip(evt,${cx},${i})"
      onmouseleave="hideSegChartTip()"/>`;
  });

  // Axis borders
  let axisSVG = `<line x1="${pad.left}" y1="${pad.top}" x2="${pad.left}" y2="${yScaleL(yL.min)}" stroke="#cbd5e1" stroke-width="1" opacity="0.5"/>`;
  axisSVG += `<line x1="${pad.left}" y1="${yScaleL(yL.min)}" x2="${W - pad.right}" y2="${yScaleL(yL.min)}" stroke="#cbd5e1" stroke-width="1" opacity="0.5"/>`;

  // Crosshair for hover
  const crosshairSVG = `<line id="seg-crosshair" x1="0" y1="${pad.top}" x2="0" y2="${yScaleL(yL.min)}" stroke="#94a3b8" stroke-width="0.75" stroke-dasharray="3,3" opacity="0" pointer-events="none"/>`;

  // Legend (HTML below chart)
  const legendHTML = `<div class="seg-chart-legend">${lines.map(l =>
    `<span class="seg-chart-legend-item"><span class="seg-chart-legend-dot" style="background:${l.color}"></span>${escHtml(l.label)}</span>`
  ).join('')}</div>`;

  wrap.innerHTML = `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" style="width:100%;height:auto;display:block;font-family:'DM Mono',ui-monospace,monospace">
    ${bandSVG}${gridSVG}${axisSVG}${xLabels}${linesSVG}${crosshairSVG}${hoverSVG}
  </svg>${legendHTML}`;
}

function showSegChartTip(evt, cx, colIdx) {
  let tip = document.getElementById('seg-chart-tip');
  if (!tip) {
    tip = document.createElement('div');
    tip.id = 'seg-chart-tip';
    tip.className = 'seg-chart-tooltip';
    el('seg-chart-wrap').appendChild(tip);
  }
  const data = _segChartTipData[colIdx];
  if (!data) return;

  // Move crosshair
  const ch = document.getElementById('seg-crosshair');
  if (ch) { ch.setAttribute('x1', cx); ch.setAttribute('x2', cx); ch.setAttribute('opacity', '0.5'); }

  let rows = '';
  data.vals.forEach(v => {
    rows += `<div style="display:flex;align-items:center;gap:6px;margin-top:3px"><span style="width:8px;height:8px;border-radius:50%;background:${v.color};flex-shrink:0"></span><span>${escHtml(v.label)}</span><strong style="margin-left:auto;font-family:'DM Mono',monospace">${v.val}</strong></div>`;
  });

  tip.innerHTML = `<div style="font-weight:700;margin-bottom:4px;font-size:var(--fs-base)">${data.dateLabel}</div>${rows}`;
  const wrap = el('seg-chart-wrap');
  const svg = wrap.querySelector('svg');
  if (!svg) return;
  const rect = svg.getBoundingClientRect();
  const wRect = wrap.getBoundingClientRect();
  const scaleX = rect.width / 960;
  const left = (cx * scaleX) + (rect.left - wRect.left);
  tip.style.display = 'block';
  // Flip to left side if too close to right edge
  const tipW = tip.offsetWidth || 160;
  if (left + tipW + 20 > wRect.width) {
    tip.style.left = (left - tipW - 14) + 'px';
  } else {
    tip.style.left = (left + 14) + 'px';
  }
  tip.style.top = '8px';
}

function hideSegChartTip() {
  const tip = document.getElementById('seg-chart-tip');
  if (tip) tip.style.display = 'none';
  const ch = document.getElementById('seg-crosshair');
  if (ch) ch.setAttribute('opacity', '0');
}

/* ── Segment Chart Analysis ─────────────────────────────── */
function _buildSegChartAnalysis(data) {
  const wrap = el('seg-chart-analysis');
  if (!wrap) return;

  const metric = _segChartMetric || 'score';
  const cfg = METRIC_CFG[metric] || METRIC_CFG.score;
  const rangeDays = _segRangeToDays(_segChartRange);
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - rangeDays);
  cutoff.setHours(0, 0, 0, 0);

  // Get segments to analyze
  let chartSegs;
  if (_segChartSelected.length > 0) {
    chartSegs = data.filter(s => _segChartSelected.includes(s.tag || s.key || _segLabel(s)));
  } else {
    chartSegs = data;
  }

  // Build time series for each segment
  const series = [];
  chartSegs.forEach((seg, i) => {
    const pts = aggregateSegmentByDay(seg.custs, metric, cutoff);
    if (pts.length >= 2) {
      const label = _segLabel(seg);
      const color = SEG_CHART_COLORS[data.indexOf(seg) % SEG_CHART_COLORS.length];
      const startVal = pts[0].avg;
      const endVal = pts[pts.length - 1].avg;
      const delta = endVal - startVal;
      // Compute std dev
      const mean = pts.reduce((s, p) => s + p.avg, 0) / pts.length;
      const variance = pts.reduce((s, p) => s + Math.pow(p.avg - mean, 2), 0) / pts.length;
      const stdDev = Math.sqrt(variance);
      // Half-period split for momentum
      const mid = Math.floor(pts.length / 2);
      const firstHalfDelta = pts[mid].avg - pts[0].avg;
      const secondHalfDelta = pts[pts.length - 1].avg - pts[mid].avg;
      const tag = seg.tag || seg.key || label;
      series.push({ seg, label, tag, color, pts, startVal, endVal, delta, mean, stdDev, firstHalfDelta, secondHalfDelta });
    }
  });

  if (series.length < 1) { wrap.innerHTML = ''; return; }

  const _ai = (path) => `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">${path}</svg>`;
  const icons = {
    momentum: _ai('<polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>'),
    corr:     _ai('<circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>'),
    risk:     _ai('<path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>'),
    dollar:   _ai('<line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>'),
    signal:   _ai('<path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/>'),
    drop:     _ai('<polyline points="22 17 13.5 8.5 8.5 13.5 2 7"/><polyline points="16 17 22 17 22 11"/>'),
  };

  const insights = [];
  const rangeLabel = _segChartRange;
  const metricLabel = cfg.label;
  const halfLabel = rangeDays <= 30 ? Math.round(rangeDays / 2) + 'd' : Math.round(rangeDays / 60) + 'mo';

  // ── 1. Momentum shift - segment was heading one way but recently reversed ──
  // This is NOT visible at a glance since the overall delta may look flat
  series.forEach(s => {
    const accel = s.secondHalfDelta - s.firstHalfDelta;
    const threshold = Math.max(2, Math.abs(s.delta) * 0.5);
    if (Math.abs(accel) < threshold) return;
    // Only interesting if the halves disagree or the acceleration is dramatic
    const reversed = (s.firstHalfDelta > 0.5 && s.secondHalfDelta < -0.5) || (s.firstHalfDelta < -0.5 && s.secondHalfDelta > 0.5);
    const accelerating = !reversed && Math.abs(s.secondHalfDelta) > Math.abs(s.firstHalfDelta) * 2;
    if (!reversed && !accelerating) return;
    const f = v => (v >= 0 ? '+' : '') + cfg.fmt(v);
    if (reversed) {
      const wasDir = s.firstHalfDelta > 0 ? 'climbing' : 'declining';
      const nowDir = s.secondHalfDelta > 0 ? 'recovering' : 'pulling back';
      insights.push({
        score: Math.abs(accel) + 3,
        icon: icons.momentum,
        color: s.secondHalfDelta > 0 ? 'var(--green)' : 'var(--red)',
        bg: s.secondHalfDelta > 0 ? 'var(--green-l)' : 'var(--red-l)',
        label: 'Momentum Shift',
        tags: [s.tag],
        text: `<strong>${escHtml(s.label)}</strong> was ${wasDir} (${f(s.firstHalfDelta)}) in the first half but is now ${nowDir} (${f(s.secondHalfDelta)}) - the overall ${rangeLabel} number masks this recent change in direction.`
      });
    } else {
      const dir = s.secondHalfDelta > 0 ? 'accelerating upward' : 'accelerating downward';
      insights.push({
        score: Math.abs(accel),
        icon: icons.momentum,
        color: s.secondHalfDelta > 0 ? 'var(--green)' : 'var(--amber)',
        bg: s.secondHalfDelta > 0 ? 'var(--green-l)' : 'var(--amber-l)',
        label: 'Accelerating',
        tags: [s.tag],
        text: `<strong>${escHtml(s.label)}</strong> is ${dir} - moved ${f(s.secondHalfDelta)} in the recent ${halfLabel} vs ${f(s.firstHalfDelta)} in the prior ${halfLabel}. The pace of change is picking up.`
      });
    }
  });

  // ── 2. Cross-signal: metric change vs health score (only when metric ≠ score) ──
  // Reveals whether this metric actually impacts health, which isn't visible on a single chart
  if (metric !== 'score' && series.length >= 2) {
    const scoreSeries = [];
    chartSegs.forEach(seg => {
      const pts = aggregateSegmentByDay(seg.custs, 'score', cutoff);
      if (pts.length >= 2) {
        scoreSeries.push({ label: _segLabel(seg), sDelta: pts[pts.length - 1].avg - pts[0].avg });
      }
    });
    if (scoreSeries.length >= 2) {
      const pairs = series.map(s => {
        const sc = scoreSeries.find(ss => ss.label === s.label);
        return sc ? { label: s.label, mDelta: s.delta, sDelta: sc.sDelta } : null;
      }).filter(Boolean);
      // Look for the outlier: metric went one way, score went the other - that's the non-obvious one
      const outliers = pairs.filter(p => (p.mDelta > 1 && p.sDelta < -1) || (p.mDelta < -1 && p.sDelta > 1));
      if (outliers.length > 0) {
        const ex = outliers.reduce((a, b) => Math.abs(b.mDelta) + Math.abs(b.sDelta) > Math.abs(a.mDelta) + Math.abs(a.sDelta) ? b : a);
        const mDir = ex.mDelta > 0 ? 'improved' : 'declined';
        const sDir = ex.sDelta > 0 ? 'improved' : 'dropped';
        const exSeries = series.find(ss => ss.label === ex.label);
        insights.push({
          score: Math.abs(ex.mDelta) + Math.abs(ex.sDelta),
          icon: icons.corr,
          color: 'var(--amber)',
          bg: 'var(--amber-l)',
          label: 'Disconnected Signal',
          tags: exSeries ? [exSeries.tag] : [],
          text: `<strong>${escHtml(ex.label)}</strong>'s ${metricLabel} ${mDir} (${ex.mDelta > 0 ? '+' : ''}${cfg.fmt(ex.mDelta)}) but their Health Score ${sDir} (${ex.sDelta > 0 ? '+' : ''}${Math.round(ex.sDelta)}) - something else is driving score changes in this segment.`
        });
      } else {
        // Check for strong positive correlation - metric and score moving together
        const sameDir = pairs.filter(p => (p.mDelta > 1 && p.sDelta > 1) || (p.mDelta < -1 && p.sDelta < -1));
        if (sameDir.length >= 2 && sameDir.length === pairs.length) {
          const ex = sameDir.reduce((a, b) => Math.abs(b.mDelta) > Math.abs(a.mDelta) ? b : a);
          const exS = series.find(ss => ss.label === ex.label);
          insights.push({
            score: sameDir.length * 1.5,
            icon: icons.signal,
            color: 'var(--blue)',
            bg: 'var(--blue-l,#dbeafe)',
            label: 'Strong Signal',
            tags: exS ? [exS.tag] : [],
            text: `${metricLabel} changes are tracking Health Score changes across all segments - this metric appears to be a reliable leading indicator. <strong>${escHtml(ex.label)}</strong> shows the clearest link.`
          });
        }
      }
    }
  }

  // ── 3. MRR concentration risk - which segments hold the $ ──
  // Not visible on the metric chart at all, adds financial context
  if (series.length >= 2) {
    const totalMRR = chartSegs.reduce((s, seg) => s + (seg.totalMRR || seg.custs.reduce((t, c) => t + (c.mrr || 0), 0)), 0);
    if (totalMRR > 0) {
      const segMRR = chartSegs.map(seg => {
        const mrr = seg.totalMRR || seg.custs.reduce((t, c) => t + (c.mrr || 0), 0);
        const pct = Math.round(mrr / totalMRR * 100);
        const s = series.find(x => x.label === _segLabel(seg));
        return { label: _segLabel(seg), mrr, pct, delta: s ? s.delta : 0, tag: s ? s.tag : (seg.tag || seg.key || _segLabel(seg)) };
      }).sort((a, b) => b.mrr - a.mrr);

      // Flag: biggest MRR segment is declining
      const biggest = segMRR[0];
      if (biggest.pct >= 30 && biggest.delta < -1) {
        insights.push({
          score: biggest.pct * Math.abs(biggest.delta) * 0.1,
          icon: icons.dollar,
          color: 'var(--red)',
          bg: 'var(--red-l)',
          label: 'Revenue Exposure',
          tags: [biggest.tag],
          text: `<strong>${escHtml(biggest.label)}</strong> holds ${biggest.pct}% of segment MRR ($${fmtNum(biggest.mrr)}) and its ${metricLabel} is declining - this concentrates risk in your highest-value segment.`
        });
      }
      // Flag: small MRR segment outperforming - possible expansion opportunity
      // Skip won/upsold stages - they're already expanded by definition
      const wonTags = ['won', 'upsold', 'won / upsold', 'won/upsold'];
      const smallest = segMRR.filter(s => s.pct < 20 && s.delta > 2 && !wonTags.includes((s.tag || '').toLowerCase()));
      if (smallest.length > 0) {
        const opp = smallest.reduce((a, b) => b.delta > a.delta ? b : a);
        insights.push({
          score: opp.delta * 1.5,
          icon: icons.dollar,
          color: 'var(--green)',
          bg: 'var(--green-l)',
          label: 'Growth Opportunity',
          tags: [opp.tag],
          text: `<strong>${escHtml(opp.label)}</strong> is only ${opp.pct}% of MRR but has the strongest ${metricLabel} trajectory - healthy signals in a small segment could mean expansion potential.`
        });
      }
    }
  }

  // ── 4. Lagging risk - segment with declining customers that others don't have ──
  // Looks at per-customer variance within segments, not segment-level averages
  if (series.length >= 2 && metric === 'score') {
    chartSegs.forEach(seg => {
      const s = series.find(x => x.label === _segLabel(seg));
      if (!s) return;
      // Count how many customers in this segment are critical or risk vs others
      const riskCount = seg.custs.filter(c => c.status === 'critical' || c.status === 'risk').length;
      const riskPct = seg.custs.length ? Math.round(riskCount / seg.custs.length * 100) : 0;
      // Is the segment average OK but risk concentration is high?
      if (s.endVal >= 60 && riskPct >= 30) {
        insights.push({
          score: riskPct * 0.3,
          icon: icons.risk,
          color: 'var(--amber)',
          bg: 'var(--amber-l)',
          label: 'Hidden Risk',
          tags: [s.tag],
          text: `<strong>${escHtml(s.label)}</strong> averages ${cfg.fmt(s.endVal)} overall but ${riskPct}% of its accounts (${riskCount}/${seg.custs.length}) are at risk - the average hides a bimodal distribution of healthy and struggling accounts.`
        });
      }
    });
  }

  // ── 5. Contact gap correlation - segments with high days-since-contact and declining metric ──
  if (series.length >= 2) {
    chartSegs.forEach(seg => {
      const s = series.find(x => x.label === _segLabel(seg));
      if (!s || s.delta >= 0) return; // only flag declining segments
      const withDays = seg.custs.filter(c => c.days != null);
      if (withDays.length < 2) return;
      const avgDays = Math.round(withDays.reduce((t, c) => t + c.days, 0) / withDays.length);
      // Other segments' avg days
      const otherSegs = chartSegs.filter(x => _segLabel(x) !== _segLabel(seg));
      const otherDays = [];
      otherSegs.forEach(os => {
        const wd = os.custs.filter(c => c.days != null);
        if (wd.length) otherDays.push(Math.round(wd.reduce((t, c) => t + c.days, 0) / wd.length));
      });
      if (!otherDays.length) return;
      const otherAvg = Math.round(otherDays.reduce((t, d) => t + d, 0) / otherDays.length);
      if (avgDays > otherAvg * 1.5 && avgDays >= 10) {
        insights.push({
          score: (avgDays - otherAvg) * 0.5 + Math.abs(s.delta),
          icon: icons.risk,
          color: 'var(--amber)',
          bg: 'var(--amber-l)',
          label: 'Engagement Gap',
          tags: [s.tag],
          text: `<strong>${escHtml(s.label)}</strong> is declining and averages ${avgDays} days since last contact vs ${otherAvg} days for other segments - the lack of recent outreach may be contributing to the decline.`
        });
      }
    });
  }

  // ── 6. Drop attribution - find the worst anomalous drop and decompose what caused it ──
  {
    let worstSeg = null, worstDrop = 0, worstPeakPt = null, worstTroughPt = null, worstPeakIdx = 0, worstTroughIdx = 0;
    series.forEach(s => {
      if (s.pts.length < 5) return;
      let peakVal = s.pts[0].avg, peakIdx = 0;
      let bestDrop = 0, bestPI = 0, bestTI = 0;
      for (let i = 1; i < s.pts.length; i++) {
        if (s.pts[i].avg > peakVal) { peakVal = s.pts[i].avg; peakIdx = i; }
        const dd = peakVal - s.pts[i].avg;
        if (dd > bestDrop) { bestDrop = dd; bestPI = peakIdx; bestTI = i; }
      }
      const isScore = metric === 'score';
      if (isScore && bestDrop < 5) return;
      if (!isScore && (bestDrop / (s.pts[bestPI].avg || 1)) * 100 < 10) return;
      // Recovery check: if metric recovered >50% after the trough, skip
      const finalVal = s.pts[s.pts.length - 1].avg;
      const recov = finalVal - s.pts[bestTI].avg;
      if (bestDrop > 0 && recov / bestDrop > 0.5) return;
      const dts = [];
      for (let i = 1; i < s.pts.length; i++) dts.push(s.pts[i].avg - s.pts[i - 1].avg);
      const md = dts.reduce((a, b) => a + b, 0) / (dts.length || 1);
      const sd = Math.sqrt(dts.reduce((a, b) => a + Math.pow(b - md, 2), 0) / (dts.length || 1));
      if (sd > 0 && bestDrop < sd * 1.5) return;
      if (bestDrop > worstDrop) {
        worstDrop = bestDrop; worstSeg = s;
        worstPeakPt = s.pts[bestPI]; worstTroughPt = s.pts[bestTI];
        worstPeakIdx = bestPI; worstTroughIdx = bestTI;
      }
    });

    if (worstSeg && worstPeakPt && worstTroughPt) {
      const fmtD = d => { const dt = new Date(d); return dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }); };
      const pv = Math.round(worstPeakPt.avg), tv = Math.round(worstTroughPt.avg);
      const dropAbs = Math.round(worstDrop);
      const segCusts = worstSeg.seg.custs;

      // ── Per-customer concentration analysis ──
      const peakT = new Date(worstPeakPt.date).getTime();
      const troughT = new Date(worstTroughPt.date).getTime();
      const custDeltas = [];
      segCusts.forEach(c => {
        const hist = (c.history || []).filter(h => h.date).sort((a, b) => a.date.localeCompare(b.date));
        if (!hist.length) return;
        const findClosest = (tgt) => hist.reduce((best, h) =>
          Math.abs(new Date(h.date).getTime() - tgt) < Math.abs(new Date(best.date).getTime() - tgt) ? h : best
        );
        const pe = findClosest(peakT), te = findClosest(troughT);
        const sv = cfg.val(pe, c), ev = cfg.val(te, c);
        if (sv != null && ev != null) custDeltas.push({ name: c.name, id: c.id, delta: ev - sv });
      });
      let concentrationNote = '';
      if (custDeltas.length >= 2) {
        const declined = custDeltas.filter(d => d.delta < -0.5);
        const improved = custDeltas.filter(d => d.delta > 0.5);
        const pctDeclined = Math.round((declined.length / custDeltas.length) * 100);
        const fv2 = v => { const c2 = METRIC_CFG[metric]; return c2?.fmt ? c2.fmt(Math.abs(v)) : Math.round(Math.abs(v) * 10) / 10; };
        if (declined.length <= 2 && declined.length > 0 && custDeltas.length > 3) {
          declined.sort((a, b) => a.delta - b.delta);
          if (declined.length === 1) {
            concentrationNote = ` This was driven primarily by ${_taCustLink(declined[0].name, declined[0].id)} (down ${fv2(declined[0].delta)}) - the remaining ${custDeltas.length - 1} accounts were relatively flat.`;
          } else {
            concentrationNote = ` Driven primarily by ${_taCustLink(declined[0].name, declined[0].id)} (down ${fv2(declined[0].delta)}) and ${_taCustLink(declined[1].name, declined[1].id)} (down ${fv2(declined[1].delta)}) - most of the other ${custDeltas.length - 2} accounts were relatively flat.`;
          }
        } else if (pctDeclined >= 60) {
          if (custDeltas.length <= 5) {
            concentrationNote = ` <strong>${declined.length} of ${custDeltas.length}</strong> accounts in this segment declined during this period.`;
          } else {
            concentrationNote = ` This was a broad-based decline - <strong>${declined.length} of ${custDeltas.length}</strong> accounts (${pctDeclined}%) dropped during this period.`;
          }
        } else if (pctDeclined >= 30) {
          concentrationNote = ` <strong>${declined.length} of ${custDeltas.length}</strong> accounts (${pctDeclined}%) declined while ${improved.length} improved - a split trend worth investigating.`;
        }
      }

      // ── Day-over-day spikes (±7% or more) ──
      const dropSlice = worstSeg.pts.slice(worstPeakIdx, worstTroughIdx + 1);
      const dodSpikes = [];
      for (let i = 1; i < dropSlice.length; i++) {
        const prev = dropSlice[i - 1].avg, curr = dropSlice[i].avg;
        if (prev === 0) continue;
        const changePct = ((curr - prev) / Math.abs(prev)) * 100;
        if (Math.abs(changePct) >= 7) dodSpikes.push({ date: dropSlice[i].date, changePct, prev, curr });
      }
      let spikeNote = '';
      if (dodSpikes.length > 0) {
        dodSpikes.sort((a, b) => a.changePct - b.changePct);
        const worst = dodSpikes[0];
        const fvS = v => { const c2 = METRIC_CFG[metric]; return c2?.fmt ? c2.fmt(v) : Math.round(v * 10) / 10; };
        spikeNote = ` Sharpest single-day drop was <strong>${Math.abs(Math.round(worst.changePct))}%</strong> on ${fmtD(worst.date)} (${fvS(worst.prev)} → ${fvS(worst.curr)}).`;
        if (dodSpikes.length > 1) spikeNote += ` There were <strong>${dodSpikes.length} days</strong> during this window with day-over-day changes exceeding 7%.`;
      }

      if (metric === 'score') {
        const attribs = (typeof _attributeScoreDrop === 'function')
          ? _attributeScoreDrop(segCusts, worstPeakPt.date, worstTroughPt.date) : [];
        const negatives = attribs.filter(a => a.contribution < -0.3);
        if (negatives.length > 0) {
          const topN = negatives.slice(0, 3);
          const drivers = topN.map(a => {
            const fRaw = v => {
              if (a.unit === '%') return Math.round(v) + '%';
              if (a.unit === 'd') return Math.round(v) + ' days';
              return Math.round(v * 10) / 10;
            };
            const impact = Math.abs(Math.round(a.contribution * 10) / 10);
            if (a.signal === 'growth') {
              const cap = s => s ? s.charAt(0).toUpperCase() + s.slice(1) : 'None';
              if (a.rawStart === a.rawEnd) return null;
              return `<strong>${a.label}</strong> shifted from ${cap(a.rawStart)} to ${cap(a.rawEnd)}, costing ~${impact} pts`;
            }
            if (a.signal === 'tickets') return `<strong>${a.label}</strong> increased from ${fRaw(a.rawStart)} to ${fRaw(a.rawEnd)}, costing ~${impact} pts on the score`;
            if (a.signal === 'days') return `<strong>${a.label}</strong> increased from ${fRaw(a.rawStart)} to ${fRaw(a.rawEnd)}, costing ~${impact} pts`;
            if (a.rawEnd < a.rawStart) return `<strong>${a.label}</strong> dropped from ${fRaw(a.rawStart)} to ${fRaw(a.rawEnd)}, costing ~${impact} pts`;
            return `<strong>${a.label}</strong> moved from ${fRaw(a.rawStart)} to ${fRaw(a.rawEnd)}, costing ~${impact} pts`;
          }).filter(Boolean);
          if (drivers.length) {
            const othersStable = series.filter(s => s !== worstSeg && Math.abs(s.delta) < dropAbs * 0.3);
            const otherNote = othersStable.length > 0 ? ` Other segments held relatively steady.` : '';
            insights.push({
              score: dropAbs + 5, icon: icons.drop, color: 'var(--red)', bg: 'var(--red-l)',
              label: 'Decline Drivers', tags: [worstSeg.tag],
              text: `<strong>${escHtml(worstSeg.label)}</strong> dropped <strong>${dropAbs} points</strong> (${pv} → ${tv}) between ${fmtD(worstPeakPt.date)} and ${fmtD(worstTroughPt.date)}. ${drivers.length === 1 ? 'The primary driver was ' + drivers[0] : 'The biggest factors: ' + drivers.join('; ')}.${concentrationNote}${spikeNote}${otherNote}`
            });
          }
        }
      } else {
        const label = cfg.label;
        const fv = v => cfg.fmt ? cfg.fmt(v) : Math.round(v * 10) / 10;
        let text = `<strong>${escHtml(worstSeg.label)}</strong>'s ${label} fell <strong>${fv(worstDrop)}</strong> (${fv(worstPeakPt.avg)} → ${fv(worstTroughPt.avg)}) between ${fmtD(worstPeakPt.date)} and ${fmtD(worstTroughPt.date)}, which is larger than typical day-to-day variation for this metric.${concentrationNote}${spikeNote}`;
        const scorePts = aggregateSegmentByDay(segCusts, 'score', cutoff);
        if (scorePts.length >= 2) {
          const fn = (arr, d) => arr.reduce((best, p) => Math.abs(new Date(p.date).getTime() - new Date(d).getTime()) < Math.abs(new Date(best.date).getTime() - new Date(d).getTime()) ? p : best);
          const sp = fn(scorePts, worstPeakPt.date), st = fn(scorePts, worstTroughPt.date);
          const sd = Math.round(st.avg - sp.avg);
          if (sd < -2) text += ` During the same window, Health Score also dropped <strong>${Math.abs(sd)} points</strong>.`;
          else if (Math.abs(sd) <= 2) text += ` Health Score stayed stable during this window - other signals offset the impact.`;
        }
        insights.push({
          score: dropAbs + 3, icon: icons.drop, color: 'var(--red)', bg: 'var(--red-l)',
          label: 'Significant Decline', tags: [worstSeg.tag], text
        });
      }
    }
  }

  // Sort by score desc, paginate
  insights.sort((a, b) => b.score - a.score);
  window._segChartInsightsAll = insights;
  window._segChartInsightPage = 0;
  _renderSegChartInsightPage(wrap);
}

function _renderSegChartInsightPage(wrap) {
  if (!wrap) wrap = el('seg-chart-analysis');
  if (!wrap) return;
  const insights = window._segChartInsightsAll || [];
  const page = window._segChartInsightPage || 0;
  const perPage = 3;
  const start = page * perPage;
  const slice = insights.slice(start, start + perPage);
  const totalPages = Math.ceil(insights.length / perPage);

  if (!slice.length) { wrap.innerHTML = ''; return; }

  const hasMore = page < totalPages - 1;
  const hasPrev = page > 0;
  const pageLabel = totalPages > 1 ? ` <span style="font-size:var(--fs-xs);color:var(--muted);font-weight:400;margin-left:6px">${page + 1} of ${totalPages}</span>` : '';
  const navBtns = totalPages > 1 ? `<div style="display:flex;gap:6px;align-items:center;margin-left:auto">` +
    (hasPrev ? `<button class="btn btn-ghost btn-sm" onclick="_segChartInsightPrev()" style="font-size:var(--fs-xs);padding:2px 8px">&larr; Prev</button>` : '') +
    (hasMore ? `<button class="btn btn-ghost btn-sm" onclick="_segChartInsightNext()" style="font-size:var(--fs-xs);padding:2px 8px;background:var(--blue);color:#fff;border-color:var(--blue)">More &rarr;</button>` : '') +
    `</div>` : '';

  // Keep window._segChartInsights pointing to current page for click handlers
  window._segChartInsights = slice;

  var navRow2 = totalPages > 1 ? `<div style="display:flex;align-items:center;justify-content:flex-end;margin-bottom:8px">${pageLabel}${navBtns}</div>` : '';

  wrap.innerHTML = navRow2 +
    slice.map((ins, i) => {
      const idx = i;
      const clickable = ins.tags && ins.tags.length > 0;
      const accentCls = ins.color === 'var(--green)' ? ' ta-card-green' : ins.color === 'var(--red)' ? ' ta-card-red' : ins.color === 'var(--amber)' ? ' ta-card-amber' : '';
      return `<div class="ta-card${accentCls}${clickable ? ' ta-card-clickable' : ''}" style="border-left-color:${ins.color}" ${clickable ? `onclick="segAnalysisFocus(${idx})"` : ''}>
      <div class="ta-icon" style="background:${ins.bg};color:${ins.color}">${ins.icon}</div>
      <div>
        <div class="ta-label">${ins.label}</div>
        <div class="ta-detail">${ins.text}</div>
      </div>
    </div>`;
    }).join('');
}

function _segChartInsightNext() {
  var all = window._segChartInsightsAll || [];
  var totalPages = Math.ceil(all.length / 3);
  window._segChartInsightPage = Math.min((window._segChartInsightPage || 0) + 1, totalPages - 1);
  _renderSegChartInsightPage();
}

function _segChartInsightPrev() {
  window._segChartInsightPage = Math.max((window._segChartInsightPage || 0) - 1, 0);
  _renderSegChartInsightPage();
}

function segAnalysisFocus(idx) {
  const insights = window._segChartInsights;
  if (!insights || !insights[idx]) return;
  const tags = insights[idx].tags || [];
  if (!tags.length) return;
  // If already showing exactly these tags, toggle back to all
  if (_segChartSelected.length === tags.length && tags.every(t => _segChartSelected.includes(t))) {
    _segChartSelected = [];
  } else {
    _segChartSelected = [...tags];
  }
  _renderSegChartOnly();
}



// ── REVENUE FORECAST ───────────────────────────────────────
let _fcSortKey = 'impact';
let _fcSortDir = -1;
let _fcSearch = '';
let _fcTab = 'all';
let _fcCatFilter = 'all';

function setFcCatFilter(cat) {
  _fcCatFilter = cat;
  _renderFcTable();
}

function fcKpiDrill(cat) {
  _fcCatFilter = cat;
  _fcTab = 'all';
  ['all', 'csm', 'tier', 'renewal'].forEach(function(t) {
    var btn = el('fc-tab-' + t);
    if (btn) btn.classList.toggle('active', t === 'all');
  });
  _renderFcTable();
  var tableWrap = el('fc-table-wrap');
  if (tableWrap) tableWrap.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function _fcFilterChipsHTML() {
  function _chip(key, label, color) {
    var active = _fcCatFilter === key;
    var bg = active ? (color || 'var(--text)') : 'transparent';
    var fg = active ? '#fff' : 'var(--muted)';
    var bdr = active ? bg : 'var(--border)';
    return '<button onclick="setFcCatFilter(\'' + key + '\')" style="padding:4px 12px;font-size:var(--fs-sm);font-weight:600;border-radius:100px;border:1.5px solid ' + bdr + ';background:' + bg + ';color:' + fg + ';cursor:pointer;font-family:inherit">' + label + '</button>';
  }
  return _chip('all', 'All', 'var(--text)') +
    _chip('expand', 'Expand', 'var(--green)') +
    _chip('retain', 'Retain', 'var(--muted)') +
    _chip('contract', 'Contract', 'var(--amber)') +
    _chip('churn', 'Churn', 'var(--red)');
}

function _fcApplyCatFilter(classified) {
  if (_fcCatFilter === 'all') return classified;
  return classified.filter(function(c) { return c.fc.cat === _fcCatFilter; });
}

// ── Classification ─────────────────────────────────────────

function _fcChurnProb(score) {
  if (score < 20) return 0.80;
  if (score < 40) return 0.50;
  if (score < 60) return 0.25;
  return 0.05;
}

function _fcExpansionEst(c) {
  return expansionConfig.mode === 'flat'
    ? expansionConfig.flat
    : Math.round((c.mrr || 0) * (expansionConfig.pct / 100));
}

function _fcClassify(c) {
  const mrr = c.mrr || 0;
  if (c.lifecycle === 'churned') return { cat: 'churn', impact: -mrr, prob: 1 };

  const score = c.score || 0;
  const delta = _getDeltaNd(c, 30);
  const declining = delta !== null && delta < 0;

  // Expand: high score + growth signal or won
  if (score >= 80 && (c.growth === 'strong' || c.lifecycle === 'won')) {
    return { cat: 'expand', impact: _fcExpansionEst(c), prob: 0 };
  }
  // Churn risk: very low score
  if (score < 30) {
    const prob = _fcChurnProb(score);
    return { cat: 'churn', impact: -Math.round(mrr * prob), prob };
  }
  // Contract: mid score + declining
  if (score < 60 && declining) {
    // Linear: 40% loss at score 30, 20% at score 59
    const pct = 0.40 - 0.20 * ((score - 30) / 29);
    return { cat: 'contract', impact: -Math.round(mrr * pct), prob: 0 };
  }
  // Retain
  return { cat: 'retain', impact: 0, prob: 0 };
}

// ── Dollar formatting for chart labels ─────────────────────

function _fcFmtDollar(v) {
  const abs = Math.abs(v);
  if (abs >= 1e6) return '$' + (v / 1e6).toFixed(1) + 'M';
  if (abs >= 1e3) return '$' + Math.round(v / 1e3) + 'K';
  return '$' + fmtNum(Math.round(v));
}

// ── Waterfall Chart ────────────────────────────────────────

function _fcBuildWaterfall(start, expand, contract, churn, projected) {
  const W = 960, H = 300;
  const pad = { top: 32, right: 20, bottom: 44, left: 65 };
  const cW = W - pad.left - pad.right;
  const cH = H - pad.top - pad.bottom;

  const maxVal = Math.max(start, start + expand, projected) * 1.15;
  if (maxVal <= 0) return '<div style="color:var(--muted);padding:20px;text-align:center">No MRR data to chart</div>';

  const yScale = (v) => pad.top + cH - (v / maxVal) * cH;
  const barW = cW / 7;
  const gap = (cW - barW * 5) / 6;
  const barX = (i) => pad.left + gap + i * (barW + gap);

  let svg = `<svg viewBox="0 0 ${W} ${H}" width="100%" style="display:block;font-family:inherit">`;

  // Y-axis gridlines
  const steps = 4;
  const stepVal = maxVal / steps;
  for (let i = 0; i <= steps; i++) {
    const val = stepVal * i;
    const y = yScale(val);
    svg += `<line x1="${pad.left}" y1="${y}" x2="${W - pad.right}" y2="${y}" stroke="var(--border)" stroke-width="0.5"/>`;
    svg += `<text x="${pad.left - 8}" y="${y + 4}" text-anchor="end" font-size="13" fill="var(--muted)">${_fcFmtDollar(val)}</text>`;
  }

  // Baseline
  svg += `<line x1="${pad.left}" y1="${yScale(0)}" x2="${W - pad.right}" y2="${yScale(0)}" stroke="var(--text)" stroke-width="1"/>`;

  // Bars
  const bars = [];
  let running = start;

  // Bar 0: Starting MRR
  bars.push({ x: barX(0), top: start, bot: 0, fill: '#64748b', label: _fcFmtDollar(start), name: 'Current MRR' });

  // Bar 1: Expansion
  const expBot = running;
  running += expand;
  bars.push({ x: barX(1), top: running, bot: expBot, fill: '#16a34a', label: '+' + _fcFmtDollar(expand), name: 'Expansion', connFrom: start });

  // Bar 2: Contraction
  const conTop = running;
  running -= contract;
  bars.push({ x: barX(2), top: conTop, bot: running, fill: '#d97706', label: '-' + _fcFmtDollar(contract), name: 'Contraction', connFrom: conTop });

  // Bar 3: Churn
  const chTop = running;
  running -= churn;
  bars.push({ x: barX(3), top: chTop, bot: running, fill: '#dc2626', label: '-' + _fcFmtDollar(churn), name: 'Churn', connFrom: chTop });

  // Bar 4: Projected MRR
  const projColor = projected >= start ? '#16a34a' : '#dc2626';
  bars.push({ x: barX(4), top: projected, bot: 0, fill: projColor, label: _fcFmtDollar(projected), name: 'Projected MRR', connFrom: running });

  // Draw connector lines + bars
  for (let i = 0; i < bars.length; i++) {
    const b = bars[i];
    const y1 = yScale(b.top);
    const y2 = yScale(b.bot);
    const h = Math.max(1, y2 - y1);

    // Connector line from previous bar
    if (b.connFrom != null && i > 0) {
      const prevX = bars[i - 1].x + barW;
      const connY = yScale(b.connFrom);
      svg += `<line x1="${prevX}" y1="${connY}" x2="${b.x}" y2="${connY}" stroke="var(--muted)" stroke-width="1" stroke-dasharray="4,3" opacity="0.5"/>`;
    }

    // Bar rect with rounded top corners
    svg += `<rect x="${b.x}" y="${y1}" width="${barW}" height="${h}" rx="4" fill="${b.fill}" opacity="0.85"/>`;

    // Dollar label above bar
    svg += `<text x="${b.x + barW / 2}" y="${y1 - 8}" text-anchor="middle" font-size="14" font-weight="700" fill="${b.fill}">${b.label}</text>`;

    // Category label below
    svg += `<text x="${b.x + barW / 2}" y="${yScale(0) + 20}" text-anchor="middle" font-size="13" font-weight="500" fill="var(--text)">${b.name}</text>`;
  }

  svg += '</svg>';
  return svg;
}

// ── Analysis Insights ──────────────────────────────────────

function _fcBuildAnalysis(classified, startMRR, nrr, expandTotal, contractTotal, churnTotal) {
  const insights = [];
  const expandAccts = classified.filter(c => c.fc.cat === 'expand');
  const contractAccts = classified.filter(c => c.fc.cat === 'contract');
  const churnAccts = classified.filter(c => c.fc.cat === 'churn');

  // 1. NRR Summary
  const nrrRound = Math.round(nrr);
  let nrrTitle, nrrDetail, nrrAccent;
  if (nrrRound >= 110) {
    nrrTitle = 'Strong NRR projection at ' + nrrRound + '%';
    nrrDetail = `Expansion from <strong>${expandAccts.length}</strong> accounts (+$${fmtNum(expandTotal)}/mo) significantly outpaces risk. `;
    nrrDetail += contractAccts.length + churnAccts.length > 0
      ? `${contractAccts.length + churnAccts.length} accounts pose risk ($${fmtNum(contractTotal + churnTotal)}/mo), but net growth is strong.`
      : 'No significant contraction or churn risk detected.';
    nrrAccent = 'green';
  } else if (nrrRound >= 100) {
    nrrTitle = 'NRR projected at ' + nrrRound + '% - slight growth';
    nrrDetail = `Expansion ($${fmtNum(expandTotal)}/mo from ${expandAccts.length} accounts) edges out risk ($${fmtNum(contractTotal + churnTotal)}/mo from ${contractAccts.length + churnAccts.length} accounts). `;
    nrrDetail += 'Revenue is growing but the margin is thin. Reducing churn risk would strengthen the position.';
    nrrAccent = 'green';
  } else if (nrrRound >= 95) {
    nrrTitle = 'NRR projected at ' + nrrRound + '% - roughly flat';
    nrrDetail = `Expansion ($${fmtNum(expandTotal)}/mo from ${expandAccts.length} accounts) is being offset by risk ($${fmtNum(contractTotal + churnTotal)}/mo from ${contractAccts.length + churnAccts.length} accounts). `;
    nrrDetail += 'Focus on converting at-risk accounts to retain to push NRR above 100%.';
    nrrAccent = 'amber';
  } else {
    nrrTitle = 'NRR projected at ' + nrrRound + '% - revenue declining';
    nrrDetail = `Risk ($${fmtNum(contractTotal + churnTotal)}/mo) exceeds expansion ($${fmtNum(expandTotal)}/mo). `;
    nrrDetail += `${churnAccts.length} accounts at churn risk and ${contractAccts.length} contracting. Immediate action needed on the highest-MRR at-risk accounts.`;
    nrrAccent = 'red';
  }
  insights.push({ icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>', iconBg: nrrAccent === 'green' ? 'var(--green-l)' : nrrAccent === 'red' ? 'var(--red-l)' : 'var(--amber-l)', iconColor: nrrAccent === 'green' ? 'var(--green)' : nrrAccent === 'red' ? 'var(--red)' : 'var(--amber)', accent: nrrAccent, title: nrrTitle, detail: nrrDetail });

  // 2. Risk callout - biggest at-risk accounts
  const allRisk = [...contractAccts, ...churnAccts].sort((a, b) => Math.abs(b.fc.impact) - Math.abs(a.fc.impact));
  if (allRisk.length > 0) {
    const topRisk = allRisk.slice(0, 3);
    const totalRiskMrr = allRisk.reduce((s, c) => s + (c.mrr || 0), 0);
    const entRisk = allRisk.filter(c => c.tier === 'enterprise');
    let riskTitle = '$' + fmtNum(Math.round(totalRiskMrr)) + '/mo exposed across ' + allRisk.length + ' accounts';
    let riskDetail = topRisk.map(c => `${_taCustLink(c.name, c.id)} (score ${c.score}, $${fmtNum(c.mrr || 0)}/mo, ${c.fc.cat})`).join(', ') + '. ';
    const weightedLoss = Math.round(contractTotal + churnTotal);
    riskDetail += `Probability-weighted impact is $${fmtNum(weightedLoss)}/mo. `;
    if (entRisk.length > 0) {
      const entMrr = entRisk.reduce((s, c) => s + (c.mrr || 0), 0);
      riskDetail += `${entRisk.length} enterprise account${entRisk.length > 1 ? 's' : ''} ($${fmtNum(entMrr)}/mo) in this group - prioritize these.`;
    } else {
      const recoveryImpact = Math.round(totalRiskMrr / startMRR * 100);
      riskDetail += `Saving all at-risk accounts would protect ~${recoveryImpact} pts of NRR.`;
    }
    insights.push({ icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>', iconBg: 'var(--red-l)', iconColor: 'var(--red)', accent: 'red', title: riskTitle, detail: riskDetail });
  }

  // 3. Actionable - borderline accounts or expansion opportunity
  const borderline = classified.filter(c => c.fc.cat === 'retain' && (c.score || 0) >= 55 && (c.score || 0) <= 70 && c.renewal && c.renewal <= 90)
    .sort((a, b) => (b.mrr || 0) - (a.mrr || 0));
  if (borderline.length > 0) {
    const blMrr = borderline.reduce((s, c) => s + (c.mrr || 0), 0);
    insights.push({ icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>', iconBg: 'var(--amber-l)', iconColor: 'var(--amber)', accent: 'amber', title: borderline.length + ' borderline accounts with upcoming renewals', detail: `${borderline.length} accounts scoring 55-70 with renewals in the next 90 days ($${fmtNum(blMrr)}/mo). These could tip to contract or strengthen to expand. A proactive touchpoint now could shift the outcome. ` + borderline.slice(0, 2).map(c => `${_taCustLink(c.name, c.id)} (${c.score}, $${fmtNum(c.mrr || 0)}/mo)`).join(', ') + '.' });
  } else if (expandAccts.length > 0) {
    const expMrr = expandAccts.reduce((s, c) => s + (c.mrr || 0), 0);
    insights.push({ icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/></svg>', iconBg: 'var(--green-l)', iconColor: 'var(--green)', accent: 'green', title: expandAccts.length + ' accounts ready for expansion ($' + fmtNum(expandTotal) + '/mo potential)', detail: expandAccts.slice(0, 3).map(c => `${_taCustLink(c.name, c.id)} (score ${c.score}, $${fmtNum(c.mrr || 0)}/mo)`).join(', ') + `. These accounts have high health scores and strong growth signals - ideal candidates for upsell conversations.` });
  }

  return insights;
}

// ── Tables ─────────────────────────────────────────────────

function setFcTab(tab) {
  _fcTab = tab;
  ['all', 'csm', 'tier', 'renewal'].forEach(t => {
    var btn = el('fc-tab-' + t);
    if (btn) btn.classList.toggle('active', t === tab);
  });
  _renderFcTable();
}

function sortFcTable(key) {
  if (_fcSortKey === key) _fcSortDir *= -1;
  else { _fcSortKey = key; _fcSortDir = key === 'name' ? 1 : -1; }
  _renderFcTable();
}

function _renderFcTable() {
  var wrap = el('fc-table-wrap');
  if (!wrap) return;

  var pool = customers.filter(function(c) { return c.lifecycle !== 'churned' && passesManagerFilter(c); });
  var classified = pool.map(function(c) { return Object.assign({}, c, { fc: _fcClassify(c), delta30: _getDeltaNd(c, 30) }); });

  if (_fcTab === 'csm') return _renderFcCsm(wrap, classified);
  if (_fcTab === 'tier') return _renderFcTier(wrap, classified);
  if (_fcTab === 'renewal') return _renderFcRenewal(wrap, classified);

  // All Customers table
  var q = _fcSearch.toLowerCase();
  var list = classified;
  if (q) list = list.filter(function(c) { return (c.name || '').toLowerCase().indexOf(q) !== -1; });
  if (_fcCatFilter !== 'all') list = list.filter(function(c) { return c.fc.cat === _fcCatFilter; });

  // Sort
  list.sort(function(a, b) {
    var va, vb;
    if (_fcSortKey === 'name') { va = (a.name || '').toLowerCase(); vb = (b.name || '').toLowerCase(); return _fcSortDir * (va < vb ? -1 : va > vb ? 1 : 0); }
    if (_fcSortKey === 'mrr') { va = a.mrr || 0; vb = b.mrr || 0; }
    else if (_fcSortKey === 'score') { va = a.score || 0; vb = b.score || 0; }
    else if (_fcSortKey === 'delta30') { va = a.delta30 || 0; vb = b.delta30 || 0; }
    else if (_fcSortKey === 'renewal') { va = a.renewal || 999; vb = b.renewal || 999; }
    else if (_fcSortKey === 'category') { var o = { churn: 0, contract: 1, retain: 2, expand: 3 }; va = o[a.fc.cat] || 2; vb = o[b.fc.cat] || 2; }
    else { va = Math.abs(a.fc.impact); vb = Math.abs(b.fc.impact); }
    return _fcSortDir * ((va || 0) - (vb || 0));
  });

  var catColors = { expand: '#dcfce7', retain: '', contract: '#fef3c7', churn: '#fee2e2' };
  var catBorders = { expand: 'var(--green)', retain: 'transparent', contract: 'var(--amber)', churn: 'var(--red)' };
  var catLabels = { expand: '<span style="color:var(--green);font-weight:600">Expand</span>', retain: '<span style="color:var(--muted)">Retain</span>', contract: '<span style="color:var(--amber);font-weight:600">Contract</span>', churn: '<span style="color:var(--red);font-weight:600">Churn</span>' };

  var arrow = _fcSortDir === 1 ? ' &#9650;' : ' &#9660;';
  var th = function(key, label) {
    return '<th style="cursor:pointer;white-space:nowrap;padding:8px 10px;font-size:var(--fs-sm);color:var(--muted);font-weight:600;text-align:left;border-bottom:2px solid var(--border)" onclick="sortFcTable(\'' + key + '\')">' + label + (_fcSortKey === key ? arrow : '') + '</th>';
  };

  var html = '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap">' +
    '<input type="text" placeholder="Search customers..." value="' + escHtml(_fcSearch) + '" oninput="_fcSearch=this.value;_renderFcTable()" style="padding:6px 10px;border:1px solid var(--border);border-radius:6px;font-size:var(--fs-base);width:220px"/>' +
    _fcFilterChipsHTML() +
  '</div>';
  html += '<div style="max-height:500px;overflow-y:auto"><table class="ct" style="width:100%;border-collapse:collapse">';
  html += '<thead><tr>' + th('name', 'Customer') + th('mrr', 'MRR') + th('score', 'Score') + th('delta30', '\u039430d') + th('renewal', 'Renewal') + th('category', 'Forecast') + th('impact', 'Impact') + '</tr></thead>';
  html += '<tbody>';

  list.forEach(function(c) {
    var bg = catColors[c.fc.cat] || '';
    var border = catBorders[c.fc.cat] || 'transparent';
    var d = c.delta30;
    var dStr = d === null ? '-' : (d > 0 ? '<span style="color:var(--green)">+' + Math.round(d) + '</span>' : d < 0 ? '<span style="color:var(--red)">' + Math.round(d) + '</span>' : '0');
    var ren = c.renewal != null ? c.renewal + 'd' : '-';
    var imp = c.fc.impact;
    var impStr = imp > 0 ? '<span style="color:var(--green)">+$' + fmtNum(imp) + '</span>' : imp < 0 ? '<span style="color:var(--red)">-$' + fmtNum(Math.abs(imp)) + '</span>' : '-';

    html += '<tr style="border-left:3px solid ' + border + ';background:' + (bg ? bg : 'transparent') + '">';
    html += '<td style="padding:7px 10px;font-weight:600"><a href="#" onclick="event.preventDefault();openDetail(\'' + escHtml(c.id) + '\')" style="color:var(--blue);text-decoration:none">' + escHtml(c.name) + '</a></td>';
    html += '<td style="padding:7px 10px">$' + fmtNum(c.mrr || 0) + '</td>';
    html += '<td style="padding:7px 10px">' + (c.score || 0) + '</td>';
    html += '<td style="padding:7px 10px">' + dStr + '</td>';
    html += '<td style="padding:7px 10px">' + ren + '</td>';
    html += '<td style="padding:7px 10px">' + (catLabels[c.fc.cat] || '') + '</td>';
    html += '<td style="padding:7px 10px;font-weight:600">' + impStr + '</td>';
    html += '</tr>';
  });

  html += '</tbody></table></div>';
  wrap.innerHTML = html;
}

function _renderFcCsm(wrap, classified) {
  var filtered = _fcApplyCatFilter(classified);
  var groups = {};
  filtered.forEach(function(c) {
    var mgr = c.manager || 'Unassigned';
    if (!groups[mgr]) groups[mgr] = [];
    groups[mgr].push(c);
  });

  var rows = Object.keys(groups).map(function(mgr) {
    var accts = groups[mgr];
    var bookMrr = accts.reduce(function(s, c) { return s + (c.mrr || 0); }, 0);
    var exp = accts.filter(function(c) { return c.fc.cat === 'expand'; }).reduce(function(s, c) { return s + c.fc.impact; }, 0);
    var con = accts.filter(function(c) { return c.fc.cat === 'contract'; }).reduce(function(s, c) { return s + Math.abs(c.fc.impact); }, 0);
    var ch = accts.filter(function(c) { return c.fc.cat === 'churn'; }).reduce(function(s, c) { return s + Math.abs(c.fc.impact); }, 0);
    var proj = bookMrr + exp - con - ch;
    var nrr = bookMrr > 0 ? Math.round(proj / bookMrr * 100) : 100;
    return { mgr: mgr, bookMrr: bookMrr, nrr: nrr, exp: exp, con: con, ch: ch, count: accts.length };
  });

  rows.sort(function(a, b) { return a.nrr - b.nrr; });

  var html = '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap">' + _fcFilterChipsHTML() + '</div>';
  html += '<table class="ct" style="width:100%;border-collapse:collapse">';
  html += '<thead><tr><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">CSM</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">Book MRR</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">NRR %</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">Expansion</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">Contraction</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">Churn</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)"># Accounts</th></tr></thead><tbody>';

  rows.forEach(function(r) {
    var nrrColor = r.nrr >= 100 ? 'var(--green)' : r.nrr >= 90 ? 'var(--amber)' : 'var(--red)';
    html += '<tr>';
    html += '<td style="padding:7px 10px;font-weight:600">' + escHtml(r.mgr) + '</td>';
    html += '<td style="padding:7px 10px">$' + fmtNum(r.bookMrr) + '</td>';
    html += '<td style="padding:7px 10px;font-weight:700;color:' + nrrColor + '">' + r.nrr + '%</td>';
    html += '<td style="padding:7px 10px;color:var(--green)">+$' + fmtNum(r.exp) + '</td>';
    html += '<td style="padding:7px 10px;color:var(--amber)">-$' + fmtNum(r.con) + '</td>';
    html += '<td style="padding:7px 10px;color:var(--red)">-$' + fmtNum(r.ch) + '</td>';
    html += '<td style="padding:7px 10px">' + r.count + '</td>';
    html += '</tr>';
  });

  html += '</tbody></table>';
  wrap.innerHTML = html;
}

function _renderFcTier(wrap, classified) {
  var filtered = _fcApplyCatFilter(classified);
  var tiers = ['enterprise', 'mid', 'smb'];
  var tierLabels = { enterprise: 'Enterprise', mid: 'Mid-Market', smb: 'SMB' };

  var rows = tiers.map(function(t) {
    var accts = filtered.filter(function(c) { return c.tier === t; });
    if (!accts.length) return null;
    var bookMrr = accts.reduce(function(s, c) { return s + (c.mrr || 0); }, 0);
    var exp = accts.filter(function(c) { return c.fc.cat === 'expand'; }).reduce(function(s, c) { return s + c.fc.impact; }, 0);
    var con = accts.filter(function(c) { return c.fc.cat === 'contract'; }).reduce(function(s, c) { return s + Math.abs(c.fc.impact); }, 0);
    var ch = accts.filter(function(c) { return c.fc.cat === 'churn'; }).reduce(function(s, c) { return s + Math.abs(c.fc.impact); }, 0);
    var proj = bookMrr + exp - con - ch;
    var nrr = bookMrr > 0 ? Math.round(proj / bookMrr * 100) : 100;
    return { tier: tierLabels[t] || t, bookMrr: bookMrr, nrr: nrr, exp: exp, con: con, ch: ch, count: accts.length };
  }).filter(Boolean);

  var html = '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap">' + _fcFilterChipsHTML() + '</div>';
  html += '<table class="ct" style="width:100%;border-collapse:collapse">';
  html += '<thead><tr><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">Tier</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">Book MRR</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">NRR %</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">Expansion</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">Contraction</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)">Churn</th><th style="padding:8px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:2px solid var(--border)"># Accounts</th></tr></thead><tbody>';

  rows.forEach(function(r) {
    var nrrColor = r.nrr >= 100 ? 'var(--green)' : r.nrr >= 90 ? 'var(--amber)' : 'var(--red)';
    html += '<tr>';
    html += '<td style="padding:7px 10px;font-weight:600">' + escHtml(r.tier) + '</td>';
    html += '<td style="padding:7px 10px">$' + fmtNum(r.bookMrr) + '</td>';
    html += '<td style="padding:7px 10px;font-weight:700;color:' + nrrColor + '">' + r.nrr + '%</td>';
    html += '<td style="padding:7px 10px;color:var(--green)">+$' + fmtNum(r.exp) + '</td>';
    html += '<td style="padding:7px 10px;color:var(--amber)">-$' + fmtNum(r.con) + '</td>';
    html += '<td style="padding:7px 10px;color:var(--red)">-$' + fmtNum(r.ch) + '</td>';
    html += '<td style="padding:7px 10px">' + r.count + '</td>';
    html += '</tr>';
  });

  html += '</tbody></table>';
  wrap.innerHTML = html;
}

function _renderFcRenewal(wrap, classified) {
  var filtered = _fcApplyCatFilter(classified);
  var windows = [
    { label: 'Next 30 Days', min: 0, max: 30 },
    { label: '30-60 Days', min: 31, max: 60 },
    { label: '60-90 Days', min: 61, max: 90 }
  ];

  var html = '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px;flex-wrap:wrap">' + _fcFilterChipsHTML() + '</div>';
  windows.forEach(function(w) {
    var accts = filtered.filter(function(c) { return c.renewal != null && c.renewal >= w.min && c.renewal <= w.max; });
    if (!accts.length) return;
    accts.sort(function(a, b) { return (a.score || 0) - (b.score || 0); });

    var totalMrr = accts.reduce(function(s, c) { return s + (c.mrr || 0); }, 0);
    var atRisk = accts.filter(function(c) { return (c.score || 0) < 50; });
    var riskMrr = atRisk.reduce(function(s, c) { return s + (c.mrr || 0); }, 0);

    html += '<div style="margin-bottom:16px">';
    html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px"><strong>' + w.label + '</strong><span style="color:var(--muted);font-size:var(--fs-sm)">' + accts.length + ' renewals - $' + fmtNum(totalMrr) + '/mo';
    if (atRisk.length > 0) html += ' - <span style="color:var(--red)">' + atRisk.length + ' at risk ($' + fmtNum(riskMrr) + ')</span>';
    html += '</span></div>';

    html += '<table class="ct" style="width:100%;border-collapse:collapse"><thead><tr>';
    html += '<th style="padding:6px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:1px solid var(--border)">Customer</th>';
    html += '<th style="padding:6px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:1px solid var(--border)">MRR</th>';
    html += '<th style="padding:6px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:1px solid var(--border)">Score</th>';
    html += '<th style="padding:6px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:1px solid var(--border)">Forecast</th>';
    html += '<th style="padding:6px 10px;text-align:left;font-size:var(--fs-sm);color:var(--muted);border-bottom:1px solid var(--border)">Days Out</th>';
    html += '</tr></thead><tbody>';

    accts.forEach(function(c) {
      var catLabels = { expand: '<span style="color:var(--green);font-weight:600">Expand</span>', retain: '<span style="color:var(--muted)">Retain</span>', contract: '<span style="color:var(--amber);font-weight:600">Contract</span>', churn: '<span style="color:var(--red);font-weight:600">Churn</span>' };
      var riskBg = (c.score || 0) < 50 ? '#fee2e2' : '';
      html += '<tr style="background:' + riskBg + '">';
      html += '<td style="padding:6px 10px;font-weight:600"><a href="#" onclick="event.preventDefault();openDetail(\'' + escHtml(c.id) + '\')" style="color:var(--blue);text-decoration:none">' + escHtml(c.name) + '</a></td>';
      html += '<td style="padding:6px 10px">$' + fmtNum(c.mrr || 0) + '</td>';
      html += '<td style="padding:6px 10px">' + (c.score || 0) + '</td>';
      html += '<td style="padding:6px 10px">' + (catLabels[c.fc.cat] || '') + '</td>';
      html += '<td style="padding:6px 10px">' + (c.renewal || '-') + 'd</td>';
      html += '</tr>';
    });

    html += '</tbody></table></div>';
  });

  if (!html) html = '<p style="color:var(--muted);padding:16px">No renewals in the next 90 days.</p>';
  wrap.innerHTML = html;
}

// ── Main Render ────────────────────────────────────────────

function renderForecast() { try { _renderForecast(); } catch (e) { console.error('renderForecast error:', e); } }

function _renderForecast() {
  var kpiRow = el('fc-kpi-row');
  if (!kpiRow) return;

  var pool = customers.filter(function(c) { return c.lifecycle !== 'churned' && passesManagerFilter(c); });
  var classified = pool.map(function(c) { return Object.assign({}, c, { fc: _fcClassify(c) }); });

  var startMRR = pool.reduce(function(s, c) { return s + (c.mrr || 0); }, 0);
  var expandTotal = 0, contractTotal = 0, churnTotal = 0;
  var expandCount = 0, contractCount = 0, churnCount = 0;

  classified.forEach(function(c) {
    if (c.fc.cat === 'expand') { expandTotal += c.fc.impact; expandCount++; }
    if (c.fc.cat === 'contract') { contractTotal += Math.abs(c.fc.impact); contractCount++; }
    if (c.fc.cat === 'churn') { churnTotal += Math.abs(c.fc.impact); churnCount++; }
  });

  var projectedMRR = startMRR + expandTotal - contractTotal - churnTotal;
  var nrr = startMRR > 0 ? (projectedMRR / startMRR * 100) : 100;

  // ── KPI Cards ──
  var nrrColor = nrr >= 100 ? '#0f766e' : nrr >= 90 ? '#b45309' : '#dc2626';
  var nrrBg = nrr >= 100 ? 'dash-kpi-teal' : nrr >= 90 ? 'dash-kpi-amber' : 'dash-kpi-red';
  var nrrIcon = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>';
  var upIcon = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/></svg>';
  var downIcon = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><polyline points="22 17 13.5 8.5 8.5 13.5 2 7"/><polyline points="16 17 22 17 22 11"/></svg>';
  var warnIcon = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>';

  kpiRow.innerHTML = `
    <div class="dash-kpi-card ${nrrBg}">
      <div class="dash-kpi-hd"><div class="dash-kpi-icon">${nrrIcon}</div><span class="dash-kpi-label">Projected NRR</span></div>
      <div class="dash-kpi-body"><div class="dash-kpi-num" style="color:${nrrColor}">${Math.round(nrr)}%</div><div class="dash-kpi-sub">Net Revenue Retention (90-day)</div></div>
    </div>
    <div class="dash-kpi-card dash-kpi-green" style="cursor:pointer" onclick="fcKpiDrill('expand')">
      <div class="dash-kpi-hd"><div class="dash-kpi-icon">${upIcon}</div><span class="dash-kpi-label">Expansion Pipeline</span></div>
      <div class="dash-kpi-body"><div class="dash-kpi-num" style="color:#16a34a">$${fmtNum(expandTotal)}</div><div class="dash-kpi-sub">${expandCount} account${expandCount !== 1 ? 's' : ''} with growth signals</div></div>
    </div>
    <div class="dash-kpi-card dash-kpi-amber" style="cursor:pointer" onclick="fcKpiDrill('contract')">
      <div class="dash-kpi-hd"><div class="dash-kpi-icon">${downIcon}</div><span class="dash-kpi-label">Contraction Risk</span></div>
      <div class="dash-kpi-body"><div class="dash-kpi-num" style="color:#b45309">$${fmtNum(contractTotal)}</div><div class="dash-kpi-sub">${contractCount} account${contractCount !== 1 ? 's' : ''} with declining scores</div></div>
    </div>
    <div class="dash-kpi-card dash-kpi-red" style="cursor:pointer" onclick="fcKpiDrill('churn')">
      <div class="dash-kpi-hd"><div class="dash-kpi-icon">${warnIcon}</div><span class="dash-kpi-label">Churn Risk</span></div>
      <div class="dash-kpi-body"><div class="dash-kpi-num" style="color:#dc2626">$${fmtNum(Math.round(churnTotal))}</div><div class="dash-kpi-sub">${churnCount} account${churnCount !== 1 ? 's' : ''} at risk of churning</div></div>
    </div>
  `;

  // ── Waterfall Chart ──
  var wfWrap = el('fc-waterfall-wrap');
  if (wfWrap) wfWrap.innerHTML = _fcBuildWaterfall(startMRR, expandTotal, contractTotal, churnTotal, projectedMRR);

  // ── Revenue Concentration chart ──
  var concWrap = el('fc-concentration-wrap');
  if (concWrap) {
    var sorted = classified.slice().sort(function(a, b) { return (b.mrr || 0) - (a.mrr || 0); });
    var totalMRR = sorted.reduce(function(s, c) { return s + (c.mrr || 0); }, 0) || 1;
    var top10 = sorted.slice(0, 5);
    var maxBar = top10.length ? (top10[0].mrr || 0) : 1;
    var statusColors = { critical: '#dc2626', risk: '#f59e0b', watch: '#eab308', healthy: '#10b981', expand: '#6366f1' };

    // Concentration metrics
    var top3MRR = sorted.slice(0, 3).reduce(function(s, c) { return s + (c.mrr || 0); }, 0);
    var top3Pct = (top3MRR / totalMRR * 100).toFixed(0);
    var top10MRR = top10.reduce(function(s, c) { return s + (c.mrr || 0); }, 0);
    var top10Pct = (top10MRR / totalMRR * 100).toFixed(0);
    var concentrationRisk = top3Pct > 50 ? 'high' : top3Pct > 35 ? 'moderate' : 'low';
    var concColor = concentrationRisk === 'high' ? '#dc2626' : concentrationRisk === 'moderate' ? '#f59e0b' : '#10b981';
    var concLabel = concentrationRisk === 'high' ? 'High concentration risk' : concentrationRisk === 'moderate' ? 'Moderate concentration' : 'Well diversified';

    // Warning banner
    var bannerHTML = '<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:6px;background:color-mix(in srgb, ' + concColor + ' 8%, transparent);border:1px solid color-mix(in srgb, ' + concColor + ' 20%, transparent);margin-bottom:10px">' +
      '<div style="width:8px;height:8px;border-radius:50%;background:' + concColor + ';flex-shrink:0"></div>' +
      '<span style="font-size:var(--fs-sm);color:var(--text)">' + concLabel + ' - Top 3 accounts = <strong>' + top3Pct + '%</strong> of MRR, Top 5 = <strong>' + top10Pct + '%</strong></span>' +
    '</div>';

    // Bars
    var barsHTML = top10.map(function(c, i) {
      var mrr = c.mrr || 0;
      var pct = (mrr / totalMRR * 100).toFixed(1);
      var barW = (mrr / maxBar * 100).toFixed(1);
      var sColor = statusColors[c.status] || '#94a3b8';
      var name = (c.name || 'Unknown').length > 18 ? (c.name || 'Unknown').slice(0, 17) + '...' : (c.name || 'Unknown');
      return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:' + (i < 9 ? '4' : '0') + 'px">' +
        '<div style="width:110px;display:flex;align-items:center;gap:5px;flex-shrink:0;overflow:hidden">' +
          '<div style="width:7px;height:7px;border-radius:50%;background:' + sColor + ';flex-shrink:0" title="' + (c.status || '') + '"></div>' +
          '<span style="font-size:12px;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="' + (c.name || '') + '">' + name + '</span>' +
        '</div>' +
        '<div style="flex:1;background:var(--bg);border-radius:3px;height:18px;overflow:hidden">' +
          '<div style="width:' + barW + '%;height:100%;border-radius:3px;background:' + (i < 3 ? 'linear-gradient(90deg,' + sColor + ',' + sColor + 'cc)' : sColor + '66') + ';min-width:2px"></div>' +
        '</div>' +
        '<div style="text-align:right;flex-shrink:0;white-space:nowrap"><span style="font-size:12px;font-weight:600;color:var(--text)">$' + fmtNum(Math.round(mrr)) + '</span> <span style="font-size:10px;color:var(--muted)">' + pct + '%</span></div>' +
      '</div>';
    }).join('');

    concWrap.innerHTML = bannerHTML + barsHTML;
  }

  // ── Analysis ──
  var analysisWrap = el('fc-analysis-wrap');
  if (analysisWrap) {
    var insights = _fcBuildAnalysis(classified, startMRR, nrr, expandTotal, contractTotal, churnTotal);
    if (insights.length) {
      analysisWrap.innerHTML = '<div style="font-size:var(--fs-base);font-weight:700;color:var(--text);margin-bottom:8px">Analysis</div>' +
        insights.map(function(ins) {
          var cls = ins.accent === 'green' ? 'ta-card-green' : ins.accent === 'red' ? 'ta-card-red' : ins.accent === 'amber' ? 'ta-card-amber' : '';
          return '<div class="ta-card ' + cls + '"><div class="ta-icon" style="background:' + ins.iconBg + ';color:' + ins.iconColor + '">' + ins.icon + '</div><div><div class="ta-label">' + ins.title + '</div><div class="ta-detail">' + ins.detail + '</div></div></div>';
        }).join('');
    } else {
      analysisWrap.innerHTML = '';
    }
  }

  // ── Table ──
  _renderFcTable();
}


// ── Smooth SVG Path Utility (Catmull-Rom → Cubic Bezier) ────
function _smoothPath(pts) {
  if (pts.length < 2) return '';
  if (pts.length === 2) return `M${pts[0].x},${pts[0].y}L${pts[1].x},${pts[1].y}`;
  let d = `M${pts[0].x},${pts[0].y}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)];
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const p3 = pts[Math.min(pts.length - 1, i + 2)];
    const cp1x = p1.x + (p2.x - p0.x) / 6;
    const cp1y = p1.y + (p2.y - p0.y) / 6;
    const cp2x = p2.x - (p3.x - p1.x) / 6;
    const cp2y = p2.y - (p3.y - p1.y) / 6;
    d += ` C${cp1x},${cp1y} ${cp2x},${cp2y} ${p2.x},${p2.y}`;
  }
  return d;
}

// ── Downsample screen-space points for smoother long-range lines ──
// Averages clusters of nearby points down to ~maxPts, preserving endpoints.
function _downsampleXY(pts, maxPts) {
  if (!pts || pts.length <= maxPts) return pts;
  const step = (pts.length - 1) / (maxPts - 1);
  const half = Math.ceil(step * 0.6);
  const result = [pts[0]];
  for (let i = 1; i < maxPts - 1; i++) {
    const center = Math.round(i * step);
    const lo = Math.max(0, center - half);
    const hi = Math.min(pts.length - 1, center + half);
    let sx = 0, sy = 0, n = 0;
    for (let j = lo; j <= hi; j++) { sx += pts[j].x; sy += pts[j].y; n++; }
    result.push({ x: sx / n, y: sy / n });
  }
  result.push(pts[pts.length - 1]);
  return result;
}

